$BEGIN         
\#include <drivers/adc/ad7266/adi_ad7266.h>

\#define ADC_BUF_SIZE   128u

static ADI_AD7266_HANDLE hDevice;
static uint8_t pMemory[ADI_AD7266_MEMORY_SIZE];
static uint16_t  ADCOutBuf[ADC_BUF_SIZE];

/* AD7266 event handler */
static void AD7266Handler(void *pCBParam, uint32_t Event, void *pArg)
{
    switch(Event)
    {
        case ADI_AD7266_EVENT_MISSED:
        	break;

        case ADI_AD7266_EVENT_COMPLETED:
            break;

        default:
            break;
    }
}

int main(void)
{
    ADI_AD7266_RESULT result;
    uint16_t *pBuffer;
    bool bDone = false;
    bool bAvailable = false;

    /* open the AD7266 driver */
    result = adi_ad7266_Open(0, pMemory, ADI_AD7266_MEMORY_SIZE, &hDevice);

    /* configure ACM */
    result = adi_ad7266_ConfigAcm(hDevice, 0, $ACLK, false, $TIMER);

    /*
     * Use the driver API's to configure the AD7266 and ACM
     *
     * adi_ad7266_ConfigGPTimer()
     * adi_ad7266_ConfigSport()
     * adi_ad7266_SetSerialDataMode()
     * adi_ad7266_ConfigAcmEvent()
     * adi_ad7266_EnableAcmEvent()
     */
    
    /* register the callback for ACM events */ 
    result = adi_ad7266_RegisterCallback(hDevice, AD7266Handler, 0);
    
    /* submit a buffer to receive data from the AD7266 */ 
    result = adi_ad7266_SubmitBuffer(hDevice,  &ADCOutBuf[0],
            ADC_BUF_SIZE * sizeof(uint16_t));

    /* enable the AD7266 */     
     result = adi_ad7266_Enable(hDevice, true);
     
    while(!bDone)
    {
        result = adi_ad7266_IsBufferAvailable(hDevice, &bAvailable);

        if (bAvailable)
        {
            /* Get the filled buffer */
            result = adi_ad7266_GetBuffer(hDevice, (void **)&pBuffer);

            if (pBuffer)
            {
                /* process the data and re-submit the buffer */
            }
        }
    }
}
$END

         
$BEGIN         

/* This driver is located in the ADSP-BF707 BSP and is not part of CrossCore 
 * Embedded Studio. 
 * This means that the INA230 * add-in needs to be included in the project to
 * resolve the include paths used in this code sketch.
 */

\#include <drivers/adc/ina230/adi_ina230.h>

/* TWI device instance used for communicating with the ina230 device */
\#define TWI_DEV_NUM                         0

/* TWI Bit rate */
\#define TWI_BITRATE                        100

/* TWI prescale value  */
\#define TWI_PRESCALE                       10

/* TWI Slave address for ina230 */
\#define TWI_SLAVE_ADDR                      ADI_INA230_TWI_ADDR_GND_VS

/* INA230 driver memory */
static uint8_t  Ina230Memory[ADI_INA230_MEMORY];

/* INA230 driver handle */
static ADI_INA230_HANDLE hDevice;

uint32_t main(void)
{ 
    /* driver API result code */
	ADI_INA230_RESULT result;

    float Voltage;
    uint16_t RegData;
    bool bReady = false;

    /* open the INA230 driver */
    result = adi_ina230_Open(0, Ina230Memory, &hDevice);

	/* Configure the TWI Device used for communicating with the INA230 Device */
    result = adi_ina230_ConfigTWI(hDevice, TWI_DEV_NUM, TWI_SLAVE_ADDR, TWI_BITRATE, TWI_PRESCALE);

	/* Start the conversion */
	result = adi_ina230_StartConversion(hDevice, ADI_INA230_CONV_BUS, false);

    /* Wait until the conversion is done */
	do
    {
        result = adi_ina230_IsConversionReady(hDevice, &bReady);

        if(bReady == true)
        {
            break;
        }

    } while(1);

    /* read the converted result */
	result = adi_ina230_ReadBusVoltage(hDevice, &RegData);

	/* convert to volts */
	Voltage = RegData * ADI_INA230_BUS_LSB;

	/* close the INA230 driver */
	result = adi_ina230_Close(hDevice);

    return 0;
}
$END

$BEGIN
\#include <drivers/atapi/adi_atapi.h>
\#include <stdio.h>

/* buffer for transfer */
uint8_t pBuffer[$numSects * ADI_ATAPI_SECTOR_SIZE];

int main(void)
{
    /* ATAPI driver handle */
    ADI_ATAPI_HANDLE hDevice;

    /* Used to query the Identify information */
    ADI_ATAPI_IDENTITY identity;

    /* Driver API result code */
    ADI_ATAPI_RESULT  eResult;

    /* The mode number for the transfer */
    uint32_t nMode;

#if ($mode == "Multiword DMA" || $mode == "Ultra DMA")
    /* Used to check if the driver is finished with the buffer */
    bool bBufferComplete = false;

    void *pProcessedBuffer;

#end
    /* open the ATAPI driver for device 0*/
    eResult = adi_atapi_Open(0, &hDevice);

     /* Identify the device */
    eResult =  adi_atapi_Identify(hDevice, &identity);

    /* See if we can support this mode */
#if ($mode == "Programmed IO")
    eResult = adi_atapi_GetMaxSupportedMode(hDevice, ADI_ATAPI_MODE_PIO, &nMode);
#elseif ($mode == "Multiword DMA")
    eResult = adi_atapi_GetMaxSupportedMode(hDevice, ADI_ATAPI_MODE_MDMA, &nMode);
#else
    eResult = adi_atapi_GetMaxSupportedMode(hDevice, ADI_ATAPI_MODE_UDMA, &nMode);
#end

    if(eResult != ADI_ATAPI_SUCCESS)
    {
        /* This mode is not supported on the device. */
    }

    /* Set the timing registers */
#if ($mode == "Programmed IO")
    eResult =  adi_atapi_SetTimingRegs(hDevice, ADI_ATAPI_MODE_PIO, nMode);
#elseif ($mode == "Multiword DMA")
    eResult =  adi_atapi_SetTimingRegs(hDevice, ADI_ATAPI_MODE_MDMA, nMode);
#else
    eResult =  adi_atapi_SetTimingRegs(hDevice, ADI_ATAPI_MODE_UDMA, nMode);
#end

    /* Set the device to the required transfer mode */
#if ($mode == "Programmed IO")
    eResult = adi_atapi_SetTransferMode(hDevice, ADI_ATAPI_MODE_PIO, nMode);
#elseif ($mode == "Multiword DMA")
    eResult = adi_atapi_SetTransferMode(hDevice, ADI_ATAPI_MODE_MDMA, nMode);
#else
    eResult = adi_atapi_SetTransferMode(hDevice, ADI_ATAPI_MODE_UDMA, nMode);
#end

#if ($mode == "Multiword DMA" || $mode == "Ultra DMA")
#if ($dir == "Read from the device")
    /* Submit a buffer for the transfer */
    eResult = adi_atapi_SubmitRxBuffer(hDevice, pBuffer, ADI_ATAPI_SECTOR_SIZE * $numSects);
#else
    /* Submit a buffer for the transfer */
    eResult = adi_atapi_SubmitTxBuffer(hDevice, pBuffer, ADI_ATAPI_SECTOR_SIZE * $numSects);
#end
#end

    /* Tell the device what we want to transfer */
#if ($dir == "Read from the device")
    eResult = adi_atapi_SetSectorTransfer(hDevice, $numSects, $startSector, ADI_ATAPI_READ);
#else
    eResult = adi_atapi_SetSectorTransfer(hDevice, $numSects, $startSector, ADI_ATAPI_WRITE);
#end

#if ($mode == "Multiword DMA" || $mode == "Ultra DMA")
    /* Start the transfer */
    eResult = adi_atapi_Enable(hDevice);
#else
    /* Transfer */
#if ($dir == "Read from the device")
    eResult = adi_atapi_Read(hDevice, pBuffer, ADI_ATAPI_SECTOR_SIZE * $numSects);
#else
    eResult = adi_atapi_Write(hDevice, pBuffer, ADI_ATAPI_SECTOR_SIZE * $numSects);
#end
#end

#if ($mode == "Multiword DMA" || $mode == "Ultra DMA")
    /* Get the received buffer */
#if ($dir == "Read from the device")
    eResult = adi_atapi_GetRxBuffer(hDevice, &pProcessedBuffer);
#else
    eResult = adi_atapi_GetTxBuffer(hDevice, &pProcessedBuffer);
#end
#end

    /* close the ATAPI driver */
    eResult = adi_atapi_Close(hDevice);

    return 0;
}
$END

$BEGIN
\#include <drivers/atapi/adi_atapi.h>
\#include <stdio.h>

/* buffer for transfer */
uint8_t pBuffer[$numSects * ADI_ATAPI_SECTOR_SIZE];

int main(void)
{
    /* ATAPI driver handle */
    ADI_ATAPI_HANDLE hDevice;

    /* Used to query the Identify information */
    ADI_ATAPI_IDENTITY identity;

    /* Driver API result code */
    ADI_ATAPI_RESULT  eResult;

    /* The mode number for the transfer */
    uint32_t nMode;

    /* Used to check if the driver is finished with the buffer */
    bool bBufferComplete = false;

    void *pProcessedBuffer;

    /* open the ATAPI driver for device 0*/
    eResult = adi_atapi_Open(0, &hDevice);

     /* Identify the device */
    eResult =  adi_atapi_Identify(hDevice, &identity);

    /* See if we can support this mode */
#if ($mode == "Multiword DMA")
    eResult = adi_atapi_GetMaxSupportedMode(hDevice, ADI_ATAPI_MODE_MDMA, &nMode);
#else
    eResult = adi_atapi_GetMaxSupportedMode(hDevice, ADI_ATAPI_MODE_UDMA, &nMode);
#end

    if(eResult != ADI_ATAPI_SUCCESS)
    {
        /* This mode is not supported on the device. */
    }

    /* Set the timing registers */
#if ($mode == "Multiword DMA")
    eResult =  adi_atapi_SetTimingRegs(hDevice, ADI_ATAPI_MODE_MDMA, nMode);
#else
    eResult =  adi_atapi_SetTimingRegs(hDevice, ADI_ATAPI_MODE_UDMA, nMode);
#end

    /* Set the device to the required transfer mode */
#if ($mode == "Multiword DMA")
    eResult = adi_atapi_SetTransferMode(hDevice, ADI_ATAPI_MODE_MDMA, nMode);
#else
    eResult = adi_atapi_SetTransferMode(hDevice, ADI_ATAPI_MODE_UDMA, nMode);
#end

    /* Submit a buffer for the transfer */
#if ($dir == "Read from the device")
    eResult = adi_atapi_SubmitRxBuffer(hDevice, pBuffer, ADI_ATAPI_SECTOR_SIZE * $numSects);
#else
    eResult = adi_atapi_SubmitTxBuffer(hDevice, pBuffer, ADI_ATAPI_SECTOR_SIZE * $numSects);
#end

    /* Tell the device what we want to transfer */
#if ($dir == "Read from the device")
    eResult = adi_atapi_SetSectorTransfer(hDevice, $numSects, $startSector, ADI_ATAPI_READ);
#else
    eResult = adi_atapi_SetSectorTransfer(hDevice, $numSects, $startSector, ADI_ATAPI_WRITE);
#end

    /* Start the transfer */
    eResult = adi_atapi_Enable(hDevice);

    while(bBufferComplete == false)
    {
        /* Continually loop until a buffer is available */
#if ($dir == "Read from the device")
        eResult = adi_atapi_IsRxBufferAvailable(hDevice, &bBufferComplete);
#else
        eResult = adi_atapi_IsTxBufferAvailable(hDevice, &bBufferComplete);
#end
    }

    /* Get the received buffer */
#if ($dir == "Read from the device")
    eResult = adi_atapi_GetRxBuffer(hDevice, &pProcessedBuffer);
#else
    eResult = adi_atapi_GetTxBuffer(hDevice, &pProcessedBuffer);
#end

    /* close the ATAPI driver */
    eResult = adi_atapi_Close(hDevice);

    return 0;
}
$END

$BEGIN         
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif
\#include <drivers/crc/adi_crc.h>

/* CRC Device Handle */
static ADI_CRC_HANDLE   hCrcDev;
/* Memory to handle DMA driven CRC Device */
static uint8_t          CrcDevMem[ADI_CRC_DMA_MEMORY_SIZE];
/* Data buffers for CRC DMA transfers */
static uint32_t         DataBuf[$DataWordCount];
/* Flag to register the current status of CRC device */
static bool             bCrcInProgress;
/* Flag to register data compare error */
static bool             bCrcDataCompareErr;
/* Flag to register DMA error */
static bool             bCrcDmaErr;

/*
 *  Callback from CRC Driver
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void CrcCallback(void *pCBParam, uint32_t Event, void *pArg)
{
    /* IF (Processed a CRC buffer) */
    if (Event == ADI_CRC_EVENT_BUFFER_PROCESSED)
    {
        /* Update CRC status flag */
        bCrcInProgress = false;
    }
    
    /* IF (Data compare error) */
    if (Event == ADI_CRC_EVENT_COMPARE_ERROR)
    {
        /* Register data compare error */
        bCrcDataCompareErr = true;
    }
    
    /* IF (DMA Error) */
    if (Event == ADI_CRC_EVENT_DMA_ERROR)
    {
        /* DMA error */
        bCrcDmaErr = true;
    }
}

int main(void)
{
    /* CRC Return code */
    ADI_CRC_RESULT  eResult;
    /* CRC value */
    uint32_t        Crc32Value;

    /* Initialize managed drivers and/or services */
    
    /* Open a CRC device instance */
    eResult = adi_crc_Open ($DeviceNum, &CrcDevMem[0], ADI_CRC_DMA_MEMORY_SIZE, &hCrcDev);

    /* Reset CRC registers */
    eResult = adi_crc_StopReset (hCrcDev, true, true);
    
    /* Set CRC polynomial */
    eResult = adi_crc_SetPolynomialVal (hCrcDev, $Polynomial);

    /* Sets data mirroring configuration */
    eResult = adi_crc_SetDataMirror (hCrcDev, $eDataMirror);
    
    /* Enable DMA mode for CRC */
    eResult = adi_crc_EnableDmaMode (hCrcDev, true);
    
    /* Register callback function if required */
    eResult = adi_crc_RegisterCallback (hCrcDev, CrcCallback, hCrcDev);
    
    /* Set CRC operating mode as Memory Scan Compute Compare */
    eResult = adi_crc_SetOperatingMode (hCrcDev, ADI_CRC_MODE_SCAN_COMPUTE_COMPARE);
    
    /* Set CRC data word count and Reload word count */
    eResult =  adi_crc_SetDataCount (hCrcDev, $DataWordCount, $DataReloadCount);
    
    /* 
     * Set the expected CRC32 value.
     * Pass this value as 0 if the CRC value for the the data stream is unknown. 
     * The CRC device will return a CRC data compare error at the end of 
     * CRC operation. Ignore this error and read the CRC final result register.
     * This register holds the CRC value calculated for the data stream.
     */
    eResult = adi_crc_SetExpectedVal (hCrcDev, $ExpectedVal);
    
    /* Set the current CRC status flag as CRC operation in progress */
    bCrcInProgress = true;
 
    /* Submit CRC buffer to Scan-Compute-Compare */
    eResult = adi_crc_DmaMemFillScan (hCrcDev, &DataBuf[0], $DataWordCount);
    
    /* Wait until the CRC operation is complete or CRC error */
    while (bCrcInProgress && (bCrcDataCompareErr == false) && (bCrcDmaErr == false))
    {
        /* 
         * Query the current status of CRC operation if operating in non-blocking mode 
         * This function call is not required for callback mode
         */
        eResult = adi_crc_IsCrcInProgress (hCrcDev, &bCrcInProgress);
    }
    
    /* 
     * Read the final CRC result if the CRC value for the buffer is yet to be calculated
     * This function also resets the registers that hold the final and intermediate CRC values
     */
    eResult = adi_crc_GetFinalCrcVal (hCrcDev, &Crc32Value);
    
    /* Handle CRC error, if any */
    
    /* Close CRC Device */
    eResult = adi_crc_Close (hCrcDev);

}
$END

$BEGIN         
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

\#include <drivers/crc/adi_crc.h>

/* CRC Device Handle */
static ADI_CRC_HANDLE   hCrcDev;
/* Memory to handle DMA driven CRC Device */
static uint8_t          CrcDevMem[ADI_CRC_DMA_MEMORY_SIZE];
/* Data buffers for CRC DMA transfers */
static uint32_t         DataBuf[$DataWordCount];
/* Flag to register the current status of CRC device */
static bool             bCrcInProgress;
/* Flag to register DMA error */
static bool             bCrcDmaErr;

/*
 *  Callback from CRC Driver
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void CrcCallback(void *pCBParam, uint32_t Event, void *pArg)
{
    /* IF (Processed a CRC buffer) */
    if (Event == ADI_CRC_EVENT_BUFFER_PROCESSED)
    {
        /* Update CRC status flag */
        bCrcInProgress = false;
    }

    /* IF (DMA Error) */
    if (Event == ADI_CRC_EVENT_DMA_ERROR)
    {
        /* DMA error */
        bCrcDmaErr = true;
    }
}

int main(void)
{
    /* CRC Return code */
    ADI_CRC_RESULT	eResult;

    /* Initialize managed drivers and/or services */

    /* Open a CRC device instance */
    eResult = adi_crc_Open ($DeviceNum, &CrcDevMem[0], ADI_CRC_DMA_MEMORY_SIZE, &hCrcDev);

    /* Reset CRC registers */
    eResult = adi_crc_StopReset (hCrcDev, true, true);

    /* Sets data mirroring configuration */
    eResult = adi_crc_SetDataMirror (hCrcDev, $eDataMirror);

    /* Enable DMA mode for CRC */
    eResult = adi_crc_EnableDmaMode (hCrcDev, true);

    /* Register callback function if required */
    eResult = adi_crc_RegisterCallback (hCrcDev, CrcCallback, hCrcDev);

    /* Set CRC operating mode as Data fill */
    eResult = adi_crc_SetOperatingMode (hCrcDev, ADI_CRC_MODE_FILL);

    /* Set CRC data word count and Reload word count */
    eResult =  adi_crc_SetDataCount (hCrcDev, $DataWordCount, $DataReloadCount);

    /* Set 32-bit value to be used to fill memory region */
    eResult =  adi_crc_SetMemFillVal (hCrcDev, $FillVal);

    /* Set the current CRC status flag as CRC operation in progress */
    bCrcInProgress = true;

    /* Submit CRC buffer to fill */
    eResult = adi_crc_DmaMemFillScan (hCrcDev, &DataBuf[0], $DataWordCount);

    /* Wait until the CRC operation is complete or CRC error */
    while (bCrcInProgress && (bCrcDmaErr == false))
    {
        /* 
         * Query the current status of CRC operation if operating in non-blocking mode 
         * This function call is not required for callback mode
         */
        eResult = adi_crc_IsCrcInProgress (hCrcDev, &bCrcInProgress);
    }

    /* Handle CRC error, if any */

    /* Close CRC Device */
    eResult = adi_crc_Close (hCrcDev);

}
$END

$BEGIN         
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

\#include <drivers/crc/adi_crc.h>

/* CRC Device Handle */
static ADI_CRC_HANDLE   hCrcDev;
/* Memory to handle CRC Device */
static uint8_t          CrcDevMem[ADI_CRC_DMA_MEMORY_SIZE];
/* Data buffers for CRC DMA transfers */
static uint32_t         SrcDataBuf[$DataWordCount];
static uint32_t         DestDataBuf[$DataWordCount];
/* Flag to register the current status of CRC device */
static bool             bCrcInProgress;
/* Flag to register data compare error */
static bool             bCrcDataCompareErr;
/* Flag to register DMA error */
static bool             bCrcDmaErr;

/*
 *  Callback from CRC Driver
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void CrcCallback(void *pCBParam, uint32_t Event, void *pArg)
{
    /* IF (Processed a CRC buffer) */
    if (Event == ADI_CRC_EVENT_BUFFER_PROCESSED)
    {
        /* Update CRC status flag */
        bCrcInProgress = false;
    }
    
    /* IF (Data compare error) */
    if (Event == ADI_CRC_EVENT_COMPARE_ERROR)
    {
        /* Register data compare error */
        bCrcDataCompareErr = true;
    }
    
    /* IF (DMA Error) */
    if (Event == ADI_CRC_EVENT_DMA_ERROR)
    {
        /* DMA error */
        bCrcDmaErr = true;
    }
}

int main(void)
{
    /* CRC Return code */
    ADI_CRC_RESULT	eResult;
    /* CRC value */
    uint32_t        Crc32Value;

    /* Initialize managed drivers and/or services */
    
    /* Open a CRC device instance */
    eResult = adi_crc_Open ($DeviceNum, &CrcDevMem[0], ADI_CRC_DMA_MEMORY_SIZE, &hCrcDev);

    /* Reset CRC registers */
    eResult = adi_crc_StopReset (hCrcDev, true, true);
    
    /* Set CRC polynomial */
    eResult = adi_crc_SetPolynomialVal (hCrcDev, $Polynomial);

    /* Sets data mirroring configuration */
    eResult = adi_crc_SetDataMirror (hCrcDev, $eDataMirror);
    
    /* Enable DMA mode for CRC */
    eResult = adi_crc_EnableDmaMode (hCrcDev, true);
    
    /* Register callback function if required */
    eResult = adi_crc_RegisterCallback (hCrcDev, CrcCallback, hCrcDev);
    
    /* Set CRC operating mode as Memory Transfer Compute Compare */
    eResult = adi_crc_SetOperatingMode (hCrcDev, ADI_CRC_MODE_XFER_COMPUTE_COMPARE);
    
    /* Set CRC data word count and Reload word count */
    eResult =  adi_crc_SetDataCount (hCrcDev, $DataWordCount, $DataReloadCount);
    
    /* 
     * Set the expected CRC32 value .
     * If the CRC value for the buffer is unknown, pass the expected value as 0
     * The CRC device will return a CRC data compare error at the end of 
     * CRC operation. Ignore this error and read the CRC final result register.
     * This register holds the CRC value calculated for the submitted data buffer.
     */
    eResult = adi_crc_SetExpectedVal (hCrcDev, $ExpectedVal);
    
    /* Set the current CRC status flag as CRC operation in progress */
    bCrcInProgress = true;
 
    /* Submit CRC buffer to Memory Transfer-Compute-Compare */
    eResult = adi_crc_DmaMemXfer (hCrcDev, &SrcDataBuf[0], &DestDataBuf[0], $DataWordCount);
    
    /* Wait until the CRC operation is complete or CRC error */
    while (bCrcInProgress && (bCrcDataCompareErr == false) && (bCrcDmaErr == false))
    {
        /* 
         * Query the current status of CRC operation if operating in non-blocking mode 
         * This function call is not required for callback mode
         */
        eResult = adi_crc_IsCrcInProgress (hCrcDev, &bCrcInProgress);
    }
    
    /* 
     * Read the final CRC result if the CRC value for the buffer is yet to be calculated
     * This function also resets the registers that hold the final and intermediate CRC values
     */
    eResult = adi_crc_GetFinalCrcVal (hCrcDev, &Crc32Value);
    
    /* Handle CRC error, if any */
    
    /* Close CRC Device */
    eResult = adi_crc_Close (hCrcDev);

}
$END

$BEGIN         
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

\#include <drivers/crc/adi_crc.h>

/* CRC Device Handle */
static ADI_CRC_HANDLE   hCrcDev;
/* Memory to handle CRC Device */
static uint8_t          CrcDevMem[ADI_CRC_DMA_MEMORY_SIZE];
/* Data buffer for CRC DMA transfers */
static uint32_t         DataBuf[$DataWordCount];
/* Flag to register the current status of CRC device */
static bool             bCrcInProgress;
/* Flag to register data compare error */
static bool             bCrcDataCompareErr;

/*
 *  Callback from CRC Driver
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void CrcCallback(void *pCBParam, uint32_t Event, void *pArg)
{
    /* IF (Processed a CRC buffer) */
    if (Event == ADI_CRC_EVENT_BUFFER_PROCESSED)
    {
        /* Update CRC status flag */
        bCrcInProgress = false;
    }
    
    /* IF (Data compare error) */
    if (Event == ADI_CRC_EVENT_COMPARE_ERROR)
    {
        /* Register data compare error */
        bCrcDataCompareErr = true;
    }
}

int main(void)
{
    /* CRC Return code */
    ADI_CRC_RESULT	eResult;

    /* Initialize managed drivers and/or services */
    
    /* Open a CRC device instance */
    eResult = adi_crc_Open ($DeviceNum, &CrcDevMem[0], ADI_CRC_DMA_MEMORY_SIZE, &hCrcDev);

    /* Reset CRC registers */
    eResult = adi_crc_StopReset (hCrcDev, true, true);
    
    /* Sets data mirroring configuration */
    eResult = adi_crc_SetDataMirror (hCrcDev, $eDataMirror);
    
    /* Enable DMA mode for CRC */
    eResult = adi_crc_EnableDmaMode (hCrcDev, true);
    
    /* Register callback function */
    eResult = adi_crc_RegisterCallback (hCrcDev, CrcCallback, hCrcDev);
    
    /* Set CRC operating mode as Memory Scan Data Verify */
    eResult = adi_crc_SetOperatingMode (hCrcDev, ADI_CRC_MODE_SCAN_VERIFY);
    
    /* Set CRC data word count and Reload word count */
    eResult =  adi_crc_SetDataCount (hCrcDev, $DataWordCount, $DataReloadCount);
    
    /* Set the 32-bit value that is to be used to validate a memory region */
    eResult =  adi_crc_SetMemFillVal (hCrcDev, $ExpectedVal);
    
    /* Set the current CRC status flag as CRC operation in progress */
    bCrcInProgress = true;
 
    /* Submit CRC buffer to verify */
    eResult = adi_crc_DmaMemFillScan (hCrcDev, &DataBuf[0], $DataWordCount);
    
    /* Wait until the CRC operation is complete or CRC error */
    while (bCrcInProgress && (bCrcDataCompareErr == false))
    {
        /* 
         * Query the current status of CRC operation if operating in non-blocking mode 
         * This function call is not required for callback mode
         */
        eResult = adi_crc_IsCrcInProgress (hCrcDev, &bCrcInProgress);
    }
    
    /* Handle CRC error, if any */
    
    /* Close CRC Device */
    eResult = adi_crc_Close (hCrcDev);
}
$END

$BEGIN 
\#include <ccblkfn.h>
\#include <stdio.h>
\#include <string.h>
\#include <services/int/adi_int.h>

/* Common Device Class Driver API includes */
\#include <drivers/device_class/adi_dev_class.h>
/* Audio class driver includes */
\#include <drivers/device_class/adi_dev_audio_class.h>

/* Audio Codec Device Entry Points are defined in the Low Level Device Driver */
/* This sketch is demonstrating the use of the on-chip ADSP-BF527 SSM2603 Device Entry Point */
\#include <drivers/codec/ssm2603/adi_ssm2603.h>


\#define ADI_AUDIO_PHYSICAL_DEV_NUMBER           $device
\#define     SAMPLE_RATE                         $sampleRate
\#define     WORD_LENGTH                         $wordLength
\#define     NUM_CHANNEL                         $numChannels

/* Handle to the Audio Device */
static ADI_DEV_AUDIO_HANDLE ghAudioDevice;


void CHECK_RESULT(int n) {
	if (n != ADI_DEV_CLASS_RESULT_SUCCESS) {
		printf("Failed\n");
		exit(1);
	}
}

/* Audio Sub-buffer Size to use */
\#define     ADI_AUDIO_SUB_BUFFER_SIZE           (512U)

 
/* An audio buffer to store samples in */
\#define BUFFER_SZ      (ADI_AUDIO_SUB_BUFFER_SIZE * 1000)
static char AudioBuff[BUFFER_SZ];

int main( void )
{
	uint32_t  nResult;
	void     *pInData = NULL;
	void     *pOutData = NULL;

        /* Set up buffer management variables */
	uint32_t  nAudioBufferIndex = 0;


	/* Open Audio CODEC via the Audio Class Driver API*/
	nResult = adi_dev_Audio_Open(&ADIDevAudioSSM2603EntryPoint, ADI_AUDIO_PHYSICAL_DEV_NUMBER, &ghAudioDevice);
	CHECK_RESULT(nResult);

	/* Set Audio data word length for all input channels */
	nResult = adi_dev_Audio_SetWordLength(ghAudioDevice, ADI_DEV_AUDIO_CHANNEL_ALL_IN, WORD_LENGTH);
	CHECK_RESULT(nResult);


	/* Submit Input channel sampling rate and apply cached sample rates */
	nResult = adi_dev_Audio_SetSampleRate(ghAudioDevice,
							ADI_DEV_AUDIO_CHANNEL_ALL_IN,
							SAMPLE_RATE,
							true);
	CHECK_RESULT(nResult);
	

	/* Enable Audio dataflow */
	nResult = adi_dev_AudioIn_EnableDataflow(ghAudioDevice, true);
	CHECK_RESULT(nResult);


	while( nAudioBufferIndex < BUFFER_SZ)
	{

		/* Get an Input buffer filled with valid samples */

		nResult = adi_dev_AudioIn_GetBuffer(ghAudioDevice, &pInData, ADI_AUDIO_SUB_BUFFER_SIZE);

		CHECK_RESULT(nResult);


		/* Copy/Save input samples to an Audio Buffer */
		memcpy(&AudioBuff[nAudioBufferIndex], pInData, ADI_AUDIO_SUB_BUFFER_SIZE);
		nAudioBufferIndex +=  ADI_AUDIO_SUB_BUFFER_SIZE;

		/* return the buffer to the Audio Class Driver */
		nResult = adi_dev_AudioIn_SubmitBuffer(ghAudioDevice, ADI_AUDIO_SUB_BUFFER_SIZE);
				
		CHECK_RESULT(nResult);

	}

	/* Disable audio input data flow. */
	nResult = adi_dev_AudioIn_EnableDataflow(ghAudioDevice, false); 
	CHECK_RESULT(nResult);



	/* Close the Audio CODEC */
	nResult = adi_dev_Audio_Close(ghAudioDevice);
	CHECK_RESULT(nResult);


	return 0;
}
$END

$BEGIN 
\#include <ccblkfn.h>
\#include <stdio.h>
\#include <string.h>
\#include <services/int/adi_int.h>

/* Common Device Class Driver API includes */
\#include <drivers/device_class/adi_dev_class.h>
/* Audio class driver includes */
\#include <drivers/device_class/adi_dev_audio_class.h>

/* Audio Codec Device Entry Points are defined in the Low Level Device Driver */
/* This sketch is demonstrating the use of the on-chip ADSP-BF527 SSM2603 Device Entry Point */
\#include <drivers/codec/ssm2603/adi_ssm2603.h>


\#define ADI_AUDIO_PHYSICAL_DEV_NUMBER           $device
\#define     SAMPLE_RATE                         $sampleRate
\#define     WORD_LENGTH                         $wordLength
\#define     NUM_CHANNEL                         $numChannels

/* Handle to the Audio Device */
static ADI_DEV_AUDIO_HANDLE ghAudioDevice;


void CHECK_RESULT(int n) {
	if (n != ADI_DEV_CLASS_RESULT_SUCCESS) {
		printf("Failed\n");
		exit(1);
	}
}

/* Audio Sub-buffer Size to use */
\#define     ADI_AUDIO_SUB_BUFFER_SIZE           (512U)

 
/* An audio buffer filled with audio samples */
\#define BUFFER_SZ      (ADI_AUDIO_SUB_BUFFER_SIZE * 1000)
static char AudioBuff[BUFFER_SZ];

int main( void )
{
	uint32_t  nResult;
	void     *pInData = NULL;
	void     *pOutData = NULL;

        /* Set up buffer management variables */
	uint32_t  nAudioBufferIndex = 0;


	/* Open Audio CODEC via the Audio Class Driver API*/
	nResult = adi_dev_Audio_Open(&ADIDevAudioSSM2603EntryPoint, ADI_AUDIO_PHYSICAL_DEV_NUMBER, &ghAudioDevice);
	CHECK_RESULT(nResult);

	/* Set Audio data word length for all output channels */
	nResult = adi_dev_Audio_SetWordLength(ghAudioDevice, ADI_DEV_AUDIO_CHANNEL_ALL_OUT, WORD_LENGTH);
	CHECK_RESULT(nResult);


	/* Submit output channel sampling rate and apply cached sample rates */
	nResult = adi_dev_Audio_SetSampleRate(ghAudioDevice,
							ADI_DEV_AUDIO_CHANNEL_ALL_OUT,
							SAMPLE_RATE,
							true);
	CHECK_RESULT(nResult);
	

	/* Enable Audio dataflow */
	nResult = adi_dev_AudioOut_EnableDataflow(ghAudioDevice, true);
	CHECK_RESULT(nResult);


	while( nAudioBufferIndex < BUFFER_SZ)
	{

		/* Get an empty output buffer */

		nResult = adi_dev_AudioOut_GetBuffer(ghAudioDevice, (void *) &pInData, ADI_AUDIO_SUB_BUFFER_SIZE);

		CHECK_RESULT(nResult);


		/* Copy audio samples into the output buffer */
		memcpy(pOutData, &AudioBuff[nAudioBufferIndex], ADI_AUDIO_SUB_BUFFER_SIZE);
		nAudioBufferIndex += ADI_AUDIO_SUB_BUFFER_SIZE;

		/* Send the audio samples to the Audio Class Driver for playback */
		nResult = adi_dev_AudioOut_SubmitBuffer(ghAudioDevice, ADI_AUDIO_SUB_BUFFER_SIZE);
				
		CHECK_RESULT(nResult);

	}

	/* Disable audio output data flow. */
	nResult = adi_dev_AudioOut_EnableDataflow(ghAudioDevice, false); 
	CHECK_RESULT(nResult);



	/* Close the Audio CODEC */
	nResult = adi_dev_Audio_Close(ghAudioDevice);
	CHECK_RESULT(nResult);


	return 0;
}
$END

         
$BEGIN         
\#include <drivers/hadc/adi_hadc.h>

/* Number of HADC channels used */
\#define NUM_CHANNELS 	2

/* Channel mask for enabling Channel 0 and 1 for conversion */
\#define CHNL_MASK       0xFFFC

/* HADC driver memory */
uint8_t HADCMemory[ADI_HADC_MEM_SIZE];

/* Buffer to hold the samples */
uint16_t SampleBuffer[NUM_CHANNELS];

uint32_t main(void)
{ 
    /* HADC driver handle */
    ADI_HADC_HANDLE hDevice;

    /* driver API result code */
	ADI_HADC_RESULT result;

    /* open the HADC driver */
    result = adi_hadc_Open($device, HADCMemory, &hDevice);

    /* Set the channel mask for the channels to be converted */
    result = adi_hadc_SetChannelMask(hDevice, CHNL_MASK);

    /*
     * Use the driver API's to configure HADC
     *
     * adi_hadc_SetChannelMask()
     * adi_hadc_SetSampleFreqDivFactor()
     * adi_hadc_SetNumConversions()
     */

	/* Start the conversion */
	result = adi_hadc_StartConversion(hDevice, true);

    /* read back the converted result */
	result = adi_hadc_ReadConvertedData(hDevice, 0x3, SampleBuffer);

	/* close the HADC driver */
	result = adi_hadc_Close(hDevice);

    return 0;
}
$END

 $BEGIN                 
\#include <drivers/hadc/adi_hadc.h>

/* Number of HADC channels used */
\#define NUM_CHANNELS 	2

/* Channel mask for enabling Channel 0 and 1 for conversion */
\#define CHNL_MASK 		0xFFFC


/* HADC driver memory */
uint8_t HADCMemory[ADI_HADC_MEM_SIZE];

/* Buffer to hold the samples */
uint16_t SampleBuffer[NUM_CHANNELS];

/* Flags to capture the events reported by the callback */
volatile bool bSeqComplete = false;
volatile bool bChnlComplete = false;
volatile bool bReady = false;
volatile uint32_t CompletedChnls = 0;

void Callback(void *pCBParam, uint32_t nEvent, void *pEventArg)
{
    switch(nEvent)
    {
        /*! Conversion of the given channel is complete. Then event argument
         *  indicates the completed channel number. */
        case ADI_HADC_EVENT_CHNL_CONV_COMPLETE:
            bChnlComplete = true;
            CompletedChnls = (uint32_t) pEventArg;
            break;

            /*! Conversion of all the enabled channels is complete. */
        case ADI_HADC_EVENT_CHNL_SEQ_COMPLETE:
            bSeqComplete = true;
            break;

        /*! ADC is ready for sampling. */
        case ADI_HADC_EVENT_ADC_READY:
            bReady = true;
            break;
    }


    return;
}

uint32_t main(void)
{ 
    /* HADC driver handle */
    ADI_HADC_HANDLE hDevice;

    /* driver API result code */
	ADI_HADC_RESULT result;

    /* open the HADC driver */
    result = adi_hadc_Open($device, HADCMemory, &hDevice);

	/* Register a callback with HADC driver */
	result = adi_hadc_RegisterCallback(hDevice, Callback, NULL);
	
	/* Set the channel mask for the channels to be converted */
	result = adi_hadc_SetChannelMask(hDevice, CHNL_MASK);
	
    /*
     * Use the driver API's to configure HADC
     *
     * adi_hadc_SetSampleFreqDivFactor()
     * adi_hadc_SetNumConversions()
     */

	/* Start the conversion */
	result = adi_hadc_StartConversion(hDevice, true);

	/* Wait until the conversion sequence is done */
	while(bSeqComplete == false);
	
    /* Use non-blocking call to get back the converted data */
	result = adi_hadc_GetConvertedData(hDevice, 0x3, SampleBuffer);

	/* close the HADC driver */
	result = adi_hadc_Close(hDevice);

    return 0;
}
$END

$BEGIN         
\#include <drivers/hadc/adi_hadc.h>

/* Number of HADC channels used */
\#define NUM_CHANNELS 	2

/* Channel mask for enabling Channel 0 and 1 for conversion */
\#define CHNL_MASK 		0xFFFC


/* HADC driver memory */
uint8_t HADCMemory[ADI_HADC_MEM_SIZE];

/* Buffer to hold the samples */
uint16_t SampleBuffer[NUM_CHANNELS];

uint32_t main(void)
{ 
    /* HADC driver handle */
    ADI_HADC_HANDLE hDevice;

    /* driver API result code */
	ADI_HADC_RESULT result;

    /* Flags to capture the events reported by the callback */
    bool bSeqComplete = false;

    /* open the HADC driver */
    result = adi_hadc_Open($device, HADCMemory, &hDevice);
	
	/* Set the channel mask for the channels to be converted */
	result = adi_hadc_SetChannelMask(hDevice, CHNL_MASK);
	
    /*
     * Use the driver API's to configure HADC
     *
     * adi_hadc_SetSampleFreqDivFactor()
     * adi_hadc_SetNumConversions()
     */

	/* Start the conversion */
	result = adi_hadc_StartConversion(hDevice, true);

    /* Wait until the conversion sequence is complete */
    do
    {
        adi_hadc_IsConvSeqComplete(hDevice, &bSeqComplete);
        
    } while(bSeqComplete == false);
	
    /* Use non-blocking call to get back the converted data */
	result = adi_hadc_GetConvertedData(hDevice, 0x3, SampleBuffer);

	/* close the HADC driver */
	result = adi_hadc_Close(hDevice);

    return 0;
}
$END

         
$BEGIN         
\#include <drivers/hae/adi_hae.h>
\#include <services/spu/adi_spu.h>

/* HAE device handle */
static ADI_HAE_HANDLE dev;

static uint8_t devMemory[ADI_HAE_DMA_MEMORY_SIZE];

int main(void)
{ 
    /* driver API result code */
	ADI_HAE_RESULT result;
	
	/* HAE DMA mode requires SPU master secure configuration for Rx0 (92), Rx1 (93) and Tx (94)
	 *
     * adi_spu_Init();
     * adi_spu_EnableMasterSecure()
     */
    	
	/* open the HAE driver */
	result = adi_hae_Open(0, devMemory, ADI_HAE_DMA_MEMORY_SIZE, &dev);
	if (result != ADI_HAE_SUCCESS)
	{
	    /* failed to open HAE driver */
	}
	
	/* use the driver API's to configure the HAE 
	 *
	 * adi_hae_SelectLineFreq()
	 * adi_hae_ConfigResults()
	 * adi_hae_SetVoltageLevel()
	 * adi_hae_EnableInputProcessing()
	 * adi_hae_HarmonicIndex()
	 * adi_hae_EnableChannels()
	 * adi_hae_ConfigSampleDivider()
	 */
	 
	 /* disable interrupt mode */
	 result = adi_hae_EnableInterrupt(dev, ADI_HAE_INT_RX, false);
     result = adi_hae_EnableInterrupt(dev, ADI_HAE_INT_TX, false);
  
	 /* enable DMA mode */
     result = adi_hae_EnableDMAMode(dev, true);
	 
	 /* submit buffers
	  * adi_hae_SubmitTxBuffer()
	  * adi_hae_SubmitRx0Buffer()
	  * adi_hae_SubmitRx1Buffer()
	  */
	  
	  /* start the HAE */
	  result = adi_hae_Run(dev, true);
	  
	 /* poll for buffers available
	  *
	  * adi_hae_IsTxBufferAvailable()
	  * adi_hae_GetTxBuffer()
	  *
	  * adi_hae_IsRx0BufferAvailable()
	  * adi_hae_GetRx0Buffer()
	  *
	  * adi_hae_IsRx1BufferAvailable()
	  * adi_hae_GetRx1Buffer()
	  */
	  
	  /* close the HAE driver */
	  result = adi_hae_Close(dev);
	  
	  return 0;
}
$END

$BEGIN         
\#include <drivers/keypad/adi_keypad.h>
\#include <stdio.h>
/* Managed drivers and/or services include */
/* \#include "../system/adi_initialize.h" */


/* Use the Pin Multiplexing Add-in to enable the Keypad peripheral pins. */

\#define SYSTEM_FREQ  133000000

static ADI_KEYPAD_HANDLE hDevice;
static uint8_t pMemory[ADI_KEYPAD_MEMORY_SIZE];
static ADI_KEYPAD_ROWCOL_STRUCT rowcol;
static bool bKeyPressed;

/* KEYPAD event handler */
static void KeypadHandler(void *pCBParam, uint32_t Event, void *pArg)
{
    ADI_KEYPAD_KEY_EVENT keyEvent = (ADI_KEYPAD_KEY_EVENT)Event;
    if (keyEvent == ADI_KEYPAD_EVENT_SINGLE)
    {
        bKeyPressed = true;
    }
}

int main(void)
{
    ADI_KEYPAD_RESULT result;

    bKeyPressed = false;

    /* Initialize managed drivers and/or services */
    /* adi_initComponents(); */

    result = adi_keypad_Open(0, pMemory, ADI_KEYPAD_MEMORY_SIZE,
        KeypadHandler, &rowcol, &hDevice);

    result = adi_keypad_SetIrqMode(hDevice, ADI_KEYPAD_IRQMODE_SINGLE_KEY);

    result = adi_keypad_ConfigRowCol (hDevice,
        ADI_KEYPAD_ROWCOL_0_3, ADI_KEYPAD_ROWCOL_0_3);

    result = adi_keypad_SetTimeDelay(hDevice, SYSTEM_FREQ, 100, 1000, 1000);

    result = adi_keypad_Enable(hDevice, true);

    printf("\nPress a key on the BF548 EZ-Kit Lite keypad\n");

    while(1)
    {
        if (bKeyPressed)
        {
            printf("row: %d, col: %d\n", rowcol.row, rowcol.col);

            bKeyPressed = false;
        }
    }
}	
$END

$BEGIN 
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

\#include <drivers/linkport/adi_linkport.h>
\#include <stdio.h>

\#define SIZE_OF_TX_BUFFER 256

/* flag indicating if device processing is complete */
volatile  bool bComplete = false;
/* device driver memory */
uint8_t DeviceMemory[ADI_LINKPORT_DMA_MEMORY_SIZE];
/* Tx buffers-0 */
uint32_t nBufferTx0[SIZE_OF_TX_BUFFER];
/* Tx buffers-1 */    
uint32_t nBufferTx1[SIZE_OF_TX_BUFFER];

/* device callback */
void linkportCallback(void* pHandle, uint32_t nEvent, void* pArg)
{
    ADI_LINKPORT_HANDLE pDevice = (ADI_LINKPORT_HANDLE *)pHandle;
    ADI_LINKPORT_EVENT event = (ADI_LINKPORT_EVENT)nEvent;
    uint16_t *data = (uint16_t*)pArg;

    switch (event) {
        case ADI_LINKPORT_EVENT_TX_BUFFER_PROCESSED:
            bComplete = true;
            break;
    default:
        break;
    }
}
 


int main(void)
{ 
    /* device driver handle */
    ADI_LINKPORT_HANDLE hDevice;

    /* driver API result code */
    ADI_LINKPORT_RESULT  eResult;
	

    /* open the device driver */
    eResult = adi_linkport_Open($device,$direction, DeviceMemory,ADI_LINKPORT_DMA_MEMORY_SIZE,&hDevice);

    /* Configure the linkport clock */
    eResult = adi_linkport_ConfigClock(hDevice,$Clock);

     /* Enable the DMA mode */
    eResult =  adi_linkport_EnableDMAMode(hDevice,true);

    /* Register a callback for the DMA */
    eResult = adi_linkport_RegisterCallback(hDevice, linkportCallback, NULL);	

    /* submit the first buffer*/
    eResult = adi_linkport_SubmitBuffer(hDevice,nBufferTx0,SIZE_OF_TX_BUFFER);
    /* submit the second buffer*/    
    eResult = adi_linkport_SubmitBuffer(hDevice,nBufferTx1,SIZE_OF_TX_BUFFER);	
    /* enable the device */
    eResult = adi_linkport_Enable(hDevice,true);
    /* Wait till the data transfer is over */ 
    while(!bComplete)
    {
       /* do other processing here while device is processing */
    }
    /* Disable the device */    
    eResult = adi_linkport_Enable(hDevice,false);
    /* close the device driver */
    eResult = adi_linkport_Close(hDevice);
    return 0;
}
$END

$BEGIN 
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

\#include <drivers/linkport/adi_linkport.h>
\#include <stdio.h>

\#define SIZE_OF_TX_BUFFER 256

/* flag indicating if Linkport processing is complete */
 bool bBufferComplete = false;
/* Linkport driver memory */
uint8_t DeviceMemory[ADI_LINKPORT_DMA_MEMORY_SIZE];
/* Tx buffers-0 */
uint32_t nBufferTx0[SIZE_OF_TX_BUFFER];
/* Tx buffers-1 */    
uint32_t nBufferTx1[SIZE_OF_TX_BUFFER];



int main(void)
{ 
    /* Linkport driver handle */
    ADI_LINKPORT_HANDLE hDevice;

    /* driver API result code */
    ADI_LINKPORT_RESULT  eResult;
	
    void *pProcessedBuffer;

    /* open the Linkport driver */
    eResult = adi_linkport_Open($device,$Direction, DeviceMemory,ADI_LINKPORT_DMA_MEMORY_SIZE,&hDevice);
    /* Configure the linkport clock */
    eResult =  adi_linkport_ConfigClock(hDevice ,$Clock);
     /* Enable the DMA mode */
    eResult =  adi_linkport_EnableDMAMode(hDevice,true);

    /* submit the first  buffers */
    eResult = adi_linkport_SubmitBuffer(hDevice,nBufferTx0,SIZE_OF_TX_BUFFER);
    /* submit the second buffer  */
    eResult = adi_linkport_SubmitBuffer(hDevice,nBufferTx1,SIZE_OF_TX_BUFFER);	
    /* Enable the device */
    eResult = adi_linkport_Enable(hDevice,true);
    /* Wait till the data transfer is over */ 
    while(bBufferComplete == false)
    {
      	eResult = adi_linkport_IsBufferAvailable(hDevice,&bBufferComplete);
    }

    eResult = adi_linkport_GetBuffer(hDevice,&pProcessedBuffer);

    /* Disable the device */    
    eResult = adi_linkport_Enable(hDevice,false);
    /* close the Linkport driver */
    eResult = adi_linkport_Close(hDevice);
    return 0;
}
$END

$BEGIN 
\#include <drivers/ppi/adi_ppi.h>
