    result = adi_eppi_Open($device, ADI_EPPI_DIRECTION_TX, driverMemory, (uint32_t)ADI_EPPI_MEMORY_SIZE, &hDevice);

    /*
     * Use the driver API's to configure EPPI
     *
     * adi_eppi_SetITUMode();
