     * adi_eppi_SetDataLength();
     * adi_eppi_SetDmaTransferSize();
     * adi_eppi_SetClockDivide();
     *
     * adi_eppi_SetFrameSync1();
     * adi_eppi_SetHorizontalDelay();
     * adi_eppi_SetSamplesPerLine();
     * adi_eppi_SetHorizontalCount();
     *
     * adi_eppi_SetFrameSync2();
     * adi_eppi_SetVerticalDelay();
     * adi_eppi_SetLinesPerFrame();
     * adi_eppi_SetVerticalCount();
     */

    /* Don't register a callback for the DMA, non-blocking mode */
	result = adi_eppi_RegisterCallback(hDevice, NULL, NULL);	

    /* submit the EPPI transceiver's buffers */
	result = adi_eppi_SubmitBuffer(hDevice, &TxBuffer1, 1024);
	result = adi_eppi_SubmitBuffer(hDevice, &TxBuffer2, 1024);	

	/* wait here until a buffer is available */
	while(bAvailable == false)
	{
		result = adi_eppi_IsBufferAvailable(hDevice, &bAvailable);
	}
	
	/* fetch the buffer just processed */
	result = adi_eppi_GetBuffer(hDevice, &pBuffer);

	/* close the EPPI driver */
	result = adi_eppi_Close(hDevice);

    return 0;
}
