     * adi_ppi_SetHorizontalCount();
     *
     * adi_ppi_SetFrameSync2();
     * adi_ppi_SetLinesPerFrame();
     * adi_ppi_SetVerticalCount();
     */

    /* Register a callback for the DMA */
	result = adi_ppi_RegisterCallback(hDevice, PpiCallback, NULL);	

