$BEGIN 
\#include <drivers/rotary/adi_counter.h>
\#include <stdio.h>

/* Rotary counter driver memory */
uint8_t DeviceMemory[ADI_COUNTER_MEMORY_SIZE ];

/* rotary counter callback */
static void CounterCallback(
    void        *pAppHandle,
    uint32_t     nEvent,
    void        *pArg
)
{

        bool bValidEvent= true;
   /* Detect the event type */ 
   switch (nEvent)
    {
        /* illegal gray/binary code interrupt   */
        case (uint32_t)ADI_CNT_EVENT_ILLEGAL_CODE_INT:
             printf("\nIllegal code ");
             break;

        /* Upcount interrupt                    */
        case (uint32_t)ADI_CNT_EVENT_UPCOUNT_INT :
             printf("\n%30s","Up count");
             break;

        /* Downcount interrupt                  */
        case (uint32_t)ADI_CNT_EVENT_DOWNCOUNT_INT:
             printf("\n%30s","Down count ");
             break;

        /* CNT_COUNTER == CNT_MIN interrupt     */
        case (uint32_t)ADI_CNT_EVENT_MINCOUNT_INT:
             printf("\n%30s","Minimum boundary reached ");
             break;

        /* CNT_COUNTER == CNT_MAX interrupt     */
        case (uint32_t)ADI_CNT_EVENT_MAXCOUNT_INT:
             printf("\n%30s","Maximum boundary reached ");
             break;
        /*  31 Bit overflow interrupt            */
        case (uint32_t)ADI_CNT_EVENT_OVERFLOW31_INT:
             printf("\n%30s","31 bit overflow");
             break;

        /*  15 Bitoverflow interrupt            */
        case (uint32_t)ADI_CNT_EVENT_OVERFLOW15_INT:
             printf("\n%30s","15 bit overflow");
             break;

        /* count to zero interrupt              */
        case (uint32_t)ADI_CNT_EVENT_COUNT_TO_ZERO_INT:
             printf("\n%30s","Counter value has crossed zero");
             break;

        /* CZM pin/push button interrupt        */
        case (uint32_t)ADI_CNT_EVENT_CZMPIN_INT:
             printf("\n%30s","Push-button interrupt occurred");
             break;

        /* Zero marker error interrupt          */
        case (uint32_t)ADI_CNT_EVENT_CZM_ERROR_INT:
             printf("\n%30s","Zero marker error interrupt");
             break;

        /* Counter zeroes by zero marker int    */
        case(uint32_t) ADI_CNT_EVENT_CZM_COUNTZERO_INT:
             printf("\n%30s","Counter zeroed by zero marker interrupt enable");
             break;

        default:
             bValidEvent = false;
             printf("\n%30s","Unknown event");
             break;
    }

    if(bValidEvent == true)
    {
            printf("\t EVENT %04lu \t  COUNT : %08lu \n ",nEvent,(uint32_t)pArg);
    }
}
 


int main(void)
{ 
    /* Rotary counter driver handle */
    ADI_COUNTER_HANDLE hDevice;

    /* driver API result code */
    ADI_COUNTER_RESULT  eResult;
	

    /* open the counter driver */
    if((eResult = adi_counter_Open(0,DeviceMemory,ADI_COUNTER_MEMORY_SIZE,CounterCallback, NULL,&hDevice))!=ADI_COUNTER_SUCCESS)
     {
         printf("\n\t Failed to open  the device:  %d",eResult);
         return(0);

     }
         
    /*
     * Use the driver API's to configure rotary counter
     *
     * adi_counter_SetOperationMode();
     * adi_counter_SetBoundary();
     * adi_counter_EnableInterrupt();
     * adi_counter_SetPolarity()
     */


    /* Close the device once the operation is over */ 
     if((eResult = adi_counter_Enable(hDevice,false))!= ADI_COUNTER_SUCCESS)
    {
             printf("\n\t Failed to disable the Rx:  %d",eResult);
            return(0);
    }
    /* Close the device */
     if((eResult = adi_counter_Close(hDevice))!= ADI_COUNTER_SUCCESS)
    {
             printf("\n\t Failed to close the Rx:  %d",eResult);
            return(0);
    }
}
$END

         
