/* status events */
void SincStatusCallback(void* pHandle, uint32_t event, void* pArg)
{
    if ((ADI_SINC_EVENT)event != ADI_SINC_EVENT_STATUS)
    {
    	return;
    }

    uint32_t status = (uint32_t)pArg;

    if (status & ADI_SINC_STATUS_FOVF0)
    {
        /* FIFO overflow - do something */
    }
}

/* data available event when callback mode is enabled */ 
void SincDataCallback(void* pHandle, uint32_t event, void* pArg)
{
    if ((ADI_SINC_EVENT)event != ADI_SINC_EVENT_DATA0)
    {
    	return;
    }

    /* pointer to sincData1 or sincData2
	 * uint16_t *bufferPtr = (uint16_t*)pArg; 
	 */
    
    /* do something with the data */
}

int main(void)
{ 
    /* driver API result code */
	ADI_SINC_RESULT result;
	
	/* SINC requires SPU master secure configuration for SINC0 (60)
	 *
     * adi_spu_Init();
     * adi_spu_EnableMasterSecure()
     */
    	
	/* open the SINC driver */
	result = adi_sinc_Open(0, devMemory, ADI_SINC_MEMORY_SIZE, &hDevice);
	if (result != ADI_SINC_SUCCESS)
	{
	    /* failed to open SINC driver */
	}
	
	/* register the status and data callbacks */
	result = adi_sinc_RegisterStatusCallback (hDevice, SincStatusCallback, 0);
	result = adi_sinc_RegisterDataCallback (hDevice, SincDataCallback, 0);
	
	/* Specify Group Parameters 
	 * adi_sinc_SetRateControl()
