     * adi_sinc_SetAmplitudeLimit()
     * adi_sinc_SetAmplitudeLimit()
     */
     
    /* Specify Modulator Clock frequency, phase & startup synchronization
     * adi_sinc_ConfigModClock()
     * adi_sinc_EnableModClock()
     */
     
    /* submit buffers to receive SINC data 
     * adi_sinc_SubmitBuffer()
     * adi_sinc_SubmitBuffer()
     */
     
    /* route the TRU interrupt
     * adi_sinc_EnableDataInterrupt()
     */

    /* Enable & assign used SINC filter pair, and specify interrupt masks
     * adi_sinc_SetControlIntMask()
     */
  
    /* Enable SINC 
     * adi_sinc_EnablePair()
     */
	  
    /* close the SINC driver */
	 result = adi_sinc_Close(hDevice);
	  
	return 0;
}
