$BEGIN 
\#include <drivers/spi/adi_spi.h>
\#include <stdio.h>

\#if defined(__ADSPGCC__)
#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

/* SPI driver memory */
uint8_t SPIDriverMemory[ADI_SPI_INT_MEMORY_SIZE];

int main(void)
{ 

    /* flag indicating the is a SPI transceiver available */
    static bool bAvailable = false;
    
    /* pointer to store transceiver */
    ADI_SPI_TRANSCEIVER *pTrans;

    /* SPI driver handle */
    ADI_SPI_HANDLE hDevice;

    /* driver API result code */
	ADI_SPI_RESULT result;

	/* transceiver buffers */
	uint8_t Prologue[4]  = {0x00, 0x01, 0x02, 0x03};
	uint8_t TxBuffer[8]  = {0x00, 0x01, 0x02, 0x03, 0x00, 0x01, 0x02, 0x03};
	uint8_t RxBuffer[8];

	/* transceiver configurations */
	ADI_SPI_TRANSCEIVER Transceiver1  = {&Prologue[0], 4, &TxBuffer[0], 8, &RxBuffer[0], 8};
	ADI_SPI_TRANSCEIVER Transceiver2  = {NULL,         4, &TxBuffer[0], 8, NULL,         0 };

    /* open the SPI driver */
    result = adi_spi_Open($device, SPIDriverMemory, (uint32_t)ADI_SPI_DMA_MEMORY_SIZE, &hDevice);

    /*
     * Use the driver API's to configure SPI
     *
     * adi_spi_SetMaster();
     * adi_spi_SetHwSlaveSelect();
     * adi_spi_SetSlaveSelect();
     * adi_spi_SetWordSize();
     * adi_spi_SetClock();
     */
	
    /* No callbacks required*/
	result = adi_spi_RegisterCallback(hDevice, NULL, NULL);	

    /* Disable DMA */
	result = adi_spi_EnableDmaMode(hDevice, false);

    /* submit the SPI transceiver's buffers */
	result = adi_spi_SubmitBuffer(hDevice, &Transceiver1);
	result = adi_spi_SubmitBuffer(hDevice, &Transceiver2);	

	/* wait here until a transceiver is available */
	while(bAvailable == false)
	{
		result = adi_spi_IsBufferAvailable(hDevice, &bAvailable);
	}
	
	/* fetch the transceiver buffer just processed */
	result = adi_spi_GetBuffer(hDevice, &pTrans);

	/* close the SPI driver */
	result = adi_spi_Close(hDevice);

    return 0;
}
$END

$BEGIN 
\#include <drivers/sport/adi_sport.h>
\#include <stdio.h>

\#define SIZE_OF_TX_BUFFER 256

/* flag indicating if SPORT processing is complete */
volatile  bool bComplete = false;
/* SPORT driver memory */
uint8_t DeviceMemory[ADI_SPORT_DMA_MEMORY_SIZE];
/* Tx buffers-0 */
uint8_t nBufferTx0[SIZE_OF_TX_BUFFER];
/* Tx buffers-1 */    
uint8_t nBufferTx1[SIZE_OF_TX_BUFFER];

/* SPORT callback */
void SportCallback(void* pHandle, uint32_t u32Arg, void* pArg)
{
    ADI_SPORT_HANDLE pDevice = (ADI_SPORT_HANDLE *)pHandle;
    ADI_SPORT_EVENT event = (ADI_SPORT_EVENT)u32Arg;
    uint16_t *data = (uint16_t*)pArg;

    switch (event) {
        case ADI_SPORT_EVENT_TX_BUFFER_PROCESSED:
            bComplete = true;
            break;
    default:
        break;
    }
}
 


int main(void)
{ 
    /* SPORT driver handle */
    ADI_SPORT_HANDLE hDevice;

    /* driver API result code */
    ADI_SPORT_RESULT  eResult;
	

    /* open the SPORT driver */
    eResult = adi_sport_Open($device,$direction, $mode, DeviceMemory,ADI_SPORT_DMA_MEMORY_SIZE,&hDevice);

    /*
     * Use the driver API's to configure SPORT
     *
     * adi_sport_ConfigData();
     * adi_sport_ConfigClock();
     * adi_sport_ConfigFrameSync();
     */

     /* Enable the DMA mode */
    eResult =  adi_sport_EnableDMAMode(hDevice,true);

    /* Register a callback for the DMA */
    eResult = adi_sport_RegisterCallback(hDevice, SportCallback, NULL);	

    /* submit the sport buffers */
    eResult = adi_sport_SubmitBuffer(hDevice,nBufferTx0,SIZE_OF_TX_BUFFER);
    eResult = adi_sport_SubmitBuffer(hDevice,nBufferTx1,SIZE_OF_TX_BUFFER);	

    eResult = adi_sport_Enable(hDevice,true);

    while(!bComplete)
    {
       /* do other processing here while SPORT is processing */
    }
    /* Disable the device */    
    eResult = adi_sport_Enable(hDevice,false);
    /* close the SPORT driver */
    eResult = adi_sport_Close(hDevice);
    return 0;
}
$END

