    }

    eResult = adi_sport_GetBuffer(hDevice,&pProcessedBuffer);

    /* Disable the device */    
    eResult = adi_sport_Enable(hDevice,false);
    /* close the SPORT driver */
    eResult = adi_sport_Close(hDevice);
    return 0;
}
