$BEGIN

\#if defined(__ADSPGCC__)
#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

\#include <drivers/tmu/adi_tmu.h>
\#include <adi_initialize.h>
\#include <stdint.h>
\#include <stdbool.h>

/* TMU callback */
void TMUCallback(void* pHandle, uint32_t u32Arg, void* pArg)
{
    ADI_TMU_HANDLE hDevice = (ADI_TMU_HANDLE *)pHandle;
    ADI_TMU_EVENT event = (ADI_TMU_EVENT)u32Arg;
    bool *pbEvent = (bool*)pArg;

    switch (event) {
		case ADI_TMU_EVENT_FAULT_HIGH:
			*pbEvent = true;
			break;
		default:
			break;
    }
}

int main(void)
{
	/* callback parameter */
	bool bFaultHiEvent = false;

	/* TMU driver memory */
	uint8_t TMUDriverMemory[ADI_TMU_MEMORY_SIZE];

	/* TMU driver handle */
	ADI_TMU_HANDLE hDevice;

	/* TMU driver API result code - should be ADI_TMU_SUCCESS */
	ADI_TMU_RESULT result;

	/* TMU Temperature value (Celsius) */
	float Temperature;

	/* Initialize system software */
	adi_initComponents();

	/* open the TMU driver */
	result = adi_tmu_Open(0u, TMUDriverMemory, (uint32_t)ADI_TMU_MEMORY_SIZE, &hDevice);

	/* Register the callback function */
	result = adi_tmu_RegisterCallback(hDevice, TMUCallback, &bFaultHiEvent);

	/* Enable TMU */
	result = adi_tmu_Enable(hDevice, true);

	/* Enable Temperature conversion */
	result = adi_tmu_EnableConversion(hDevice, true);

	/* Set the Alert High Temperature to same as current temperature */
	result = adi_tmu_SetEventLimitValue(hDevice, ADI_TMU_EVENT_FAULT_HIGH, $alertTemp);

	/* enable interrupt */
	adi_tmu_EnableEvent(hDevice, ADI_TMU_EVENT_FAULT_HIGH, true);

	/* wait for interrupt event */
	while(!bFaultHiEvent) { }

	/* Read the TMU temperature */
	result = adi_tmu_ReadTemperature(hDevice, &Temperature);

	/* close the TMU driver */
	result = adi_tmu_Close(hDevice);

	return 0;
}
$END

