	ADI_TMU_RESULT result;
    
    /* TMU Temperature value (Celsius) */
    float Temperature;

    /* open the TMU driver */
    result = adi_tmu_Open(0, TMUDriverMemory, (uint32_t)ADI_TMU_MEMORY_SIZE, &hDevice);

    /*
     * Use the driver API's to configure TMU
     *
     * adi_tmu_EnableAveraging();
     * adi_tmu_EnableOscillator();
     * adi_tmu_SetOscillatorDivider();
     * adi_tmu_SetGain();
     * adi_tmu_SetOffset();
     */

    /* Enable TMU */
	result = adi_tmu_Enable(hDevice, true);

    /* Enable Temperature conversion */
	result = adi_tmu_EnableConversion(hDevice, true);

    /* Temperature conversion takes at least 1 millisecond */

    /* Read the TMU temperature */
	result = adi_tmu_ReadTemperature(hDevice, &Temperature);

	/* close the TMU driver */
	result = adi_tmu_Close(hDevice);

    return 0;
}
$END

$BEGIN         
/* Use the System Configuration Add-in to install the AD7877 driver. */

\#include <drivers/touchscreen/ad7877/adi_ad7877.h>
\#include <drivers/spi/adi_spi.h>
\#include <services/gpio/adi_gpio.h>
\#include <stdio.h>
/* Managed drivers and/or services include */
/* \#include "../system/adi_initialize.h" */

/* Use the Pin Multiplexing Add-in to enable the SPI peripheral pins. */

\#define AD7877_DEV_NUM         0
\#define SPI_DEV_NUM            0
\#define SPI_SLAVE_SELECT       ADI_SPI_SSEL_ENABLE2
\#define DAV_PORT             	ADI_GPIO_PORT_B
\#define DAV_PIN              	ADI_GPIO_PIN_4
\#define DAV_PIN_INTERRUPT    	ADI_GPIO_PIN_INTERRUPT_1
\#define DAV_PIN_ASSIGN_BYTE  	ADI_GPIO_PIN_ASSIGN_BYTE_0
\#define DAV_PIN_ASSIGN_PORT  	ADI_GPIO_PIN_ASSIGN_PBL

/* Total memory required for all the GPIO callbacks */
\#define GPIO_MEM_SIZE (ADI_GPIO_CALLBACK_MEM_SIZE*2)

/* Memory for GPIO callbacks */
uint8_t GPIOCallbackMem[GPIO_MEM_SIZE];

/* Memory required for touch screen driver */
uint8_t touchScreenMem[ADI_AD7877_MEMORY_SIZE];

/* Touch screen device handle */
ADI_AD7877_HANDLE  hAD7877;

static bool bEvent = false;

/* touch screen callback */
static void AD7877Callback(void *pCBParam, uint32_t Event, void *pArg)
{
    switch(Event)
    {
        case ADI_AD7877_EVENT_INT:
            bEvent = true;
            break;
    }
}

int main(void)
{
    ADI_AD7877_RESULT result;
	uint16_t xtouch, ytouch;
    uint32_t NumCallbacks;

    /* adi_initComponents(); */

    /* configuration */
    adi_gpio_Init(GPIOCallbackMem, GPIO_MEM_SIZE, &NumCallbacks);

	/* Open the touch screen driver */
    result = adi_AD7877_Open (AD7877_DEV_NUM, touchScreenMem, ADI_AD7877_MEMORY_SIZE,
        AD7877Callback, NULL, &hAD7877 );

	/* Configure SPI */
	result = adi_AD7877_ConfigSPI (hAD7877, SPI_DEV_NUM, SPI_SLAVE_SELECT);

    result = adi_AD7877_ConfigIntPin (hAD7877, DAV_PORT, DAV_PIN, DAV_PIN_INTERRUPT,
        DAV_PIN_ASSIGN_BYTE, DAV_PIN_ASSIGN_PORT);

    /* configure the AD7877 registers
     *
     * adi_AD7877_SetControl1Reg()
     * adi_AD7877_SetControl2Reg()
     * adi_AD7877_SetSequencer1Reg()
     */
     
    /* enable interrupts */
    result = adi_AD7877_Enable(hAD7877, true);
     
    while (1)
    {
        if(bEvent)
        {
            /* read position registers */
            result = adi_AD7877_GetMeasurementResult (hAD7877,
		        ADI_AD7877_MEASUREMENT_XPOS, &xtouch);

            result = adi_AD7877_GetMeasurementResult (hAD7877,
                ADI_AD7877_MEASUREMENT_YPOS, &ytouch);

            printf(" X=%5d : Y=%5d\n", xtouch, ytouch);

            bEvent = false;
        }
    }
}
$END

