/* TWI callback */
void TwiCallback(void* pHandle, uint32_t u32Arg, void* pArg)
{
    ADI_TWI_HANDLE pDevice = (ADI_TWI_HANDLE *)pHandle;
    ADI_TWI_EVENT event = (ADI_TWI_EVENT)u32Arg;
