    switch (event) {
        case ADI_TWI_EVENT_BUFFER_PROCESSED:
        case ADI_TWI_EVENT_XMT_PROCESSED:
        case ADI_TWI_EVENT_RCV_PROCESSED:
        case ADI_TWI_EVENT_SCOMP:		
            bComplete = true;
            break;
