    ADI_TWI_HANDLE hDevice;

    /* TWI driver memory */
    uint8_t driverMemory[ADI_TWI_MEMORY_SIZE];

    /* driver API result code */
    ADI_TWI_RESULT result;
	
    /* buffer which holds data to transfer over TWI */
    uint8_t buffer[] = {1, 2, 3};

    /* open the TWI driver in master mode */
    result = adi_twi_Open($device, ADI_TWI_MASTER, driverMemory, ADI_TWI_MEMORY_SIZE, &hDevice);

    /*
     * Use the driver API's to configure TWI
     *
     * adi_twi_SetBitRate()
     * adi_twi_SetDutyCycle()
     * adi_twi_SetPrescale()
     * adi_twi_SetHardwareAddress()
     */

    /* register the callback function */
    result = adi_twi_RegisterCallback(hDevice, TwiCallback, (void*)0);

    /* submit the data to the TWI device */
    result = adi_twi_SubmitTxBuffer(hDevice, buffer, sizeof(buffer), false);

    /* enable the TWI transfer */ 
    result = adi_twi_Enable(hDevice);

    while(!bComplete)
    {
	    /* do other processing here while TWI is transmiting */
    }
    
    /* close the TWI driver */
    result = adi_twi_Close(hDevice);

    return 0;
}
$END

