uint32_t main(void)
{ 
	/* Pointer to the buffer */
	uint8_t *pBuffer;
        bool bTxFinshed = false; 
	/* buffer which holds data to transfer over UART */
    uint8_t buffer[] = {1, 2, 3};
		
	/* UART Driver Handle */
	ADI_UART_HANDLE hDevice;
	
	/* UART result code */
	ADI_UART_RESULT result;
	
	
  /* open the UART driver in Tx mode only */
    result = adi_uart_Open($device, ADI_UART_DIR_TRANSMIT, driverMemory, ADI_UART_UNIDIR_DMA_MEMORY_SIZE, &hDevice);

    /*
     * To  configure UART
     *
     * adi_uart_SetConfiguration()
     * adi_uart_SetBaudRate()
     * adi_uart_EnableDMAMode()
     */


     /* submit the data to the UART device */
    result = adi_uart_SubmitTxBuffer(hDevice, buffer, sizeof(buffer));

    /* enable the UART transfer */ 
	result = adi_uart_EnableTx(hDevice, true);

	while(bTxFinshed == false)
	{
  	    adi_uart_IsTxBufferAvailable(hDevice,&bTxFinshed);
	}
	/* Get back the transmitted buffer (Waits until the buffer is transmitted) */
	result = adi_uart_GetTxBuffer(hDevice, (void *)&pBuffer);
    
	/* close the UART driver */
	result = adi_uart_Close(hDevice);

    return 0;
}
$END

