$BEGIN
\#include <services/gpio/adi_gpio.h>
\#include <stdio.h>

\#define GPIO_MEMORY_SIZE (ADI_GPIO_CALLBACK_MEM_SIZE)

/* allocate memory for the GPIO service */
static uint8_t gpioMemory[GPIO_MEMORY_SIZE];

/* callback for receiving GPIO input events */
void gpioCallback(ADI_GPIO_PIN_INTERRUPT ePinInt, uint32_t PinIntData,  void *pCBParam)
{
	if (ePinInt == ADI_GPIO_PIN_INTERRUPT_3)
	{
		if (PinIntData & ADI_GPIO_PIN_1)
		{
            /* got a push button 2 event */
            printf("Push Button 2 pressed\n");
		}
	}
}

int main(void)
{
	ADI_GPIO_RESULT result;
	uint32_t gpioMaxCallbacks;

    /* initialize the GPIO service */
	result = adi_gpio_Init((void*)gpioMemory, GPIO_MEMORY_SIZE, &gpioMaxCallbacks);

	/* On the BF609 EZ-Board Push Button 2 is connected to Port E - Pin 1 */

	/* set the GPIO direction */
	result = adi_gpio_SetDirection(ADI_GPIO_PORT_E, ADI_GPIO_PIN_1, ADI_GPIO_DIRECTION_INPUT);

	/* set edge sense mode (PORT E is connected to Pin Interrupt 3) */
	result = adi_gpio_SetPinIntEdgeSense(ADI_GPIO_PIN_INTERRUPT_3, ADI_GPIO_PIN_1, ADI_GPIO_SENSE_RISING_EDGE);

	/* register pinint 3 callback */
	result = adi_gpio_RegisterCallback(ADI_GPIO_PIN_INTERRUPT_3, ADI_GPIO_PIN_1, gpioCallback, (void*)0);

	/* enable the pin interrupt mask */
	result = adi_gpio_EnablePinInterruptMask(ADI_GPIO_PIN_INTERRUPT_3, ADI_GPIO_PIN_1, true);

	/* wait for the GPIO input event */
	while(1) {}
}
$END

