$BEGIN
/* DMA Manager includes */
\#include <services/dma/adi_dma.h>
\#include <stdlib.h>

/*
 * Memory DMA stream to use
 * Number of Memory DMA streams and stream ID enumerations could vary based on processor family
 * Refer to relevant include file (adi_mdma_streams_xxx.h) for the complete list of
 * Memory DMA stream IDs supported by a processor.
 */
\#if defined (__ADSPBF538_FAMILY__) || defined (__ADSPBF548_FAMILY__) || defined (__ADSPBF561_FAMILY__)
/* Processors with more than one DMA controller, the Memory DMA stream IDs are different from other Blackfin processors */
\#define    MDMA_STREAM_ID      ADI_DMA_MEMDMA0_S0
\#else
/* Processors with one DMA controller */
\#define    MDMA_STREAM_ID      ADI_DMA_MEMDMA_S0
#endif

/* Macro to define the number of 1D Array Descriptors to use */
\#define    NUM_DESC            ($NumDesc)
/* Macro to define the number of bytes to copy per descriptor */
\#define    BYTES_PER_DESC      ($BytesPerDesc)
/* Macro to define the Word/Memory transfer size */
\#define    MDMA_XFER_SIZE      ($eXferSize)

/* MDMA Stream Handle */
static ADI_DMA_STREAM_HANDLE	hMemDmaStream;
/* Source DMA Handle */
ADI_DMA_CHANNEL_HANDLE          hSrcDmaChannel;
/* Destination DMA Handle */
ADI_DMA_CHANNEL_HANDLE          hDestDmaChannel;

/* Memory to handle DMA Stream */
static uint8_t MemDmaStreamMem[ADI_DMA_STREAM_REQ_MEMORY];

/* Flag to register Memory DMA copy completion */
static volatile bool bMemCopyInProgress;

/* Source and destination data buffers */
static uint8_t  SrcDataBuf [BYTES_PER_DESC * NUM_DESC];
static uint8_t  DestDataBuf [BYTES_PER_DESC * NUM_DESC];

/***** Instances to handle 1D Array descriptor transfers ******/
static  ADI_DMA_DESC_ARRAY_1D_MODE  Src_1DArray[NUM_DESC];
static  ADI_DMA_DESC_ARRAY_1D_MODE  Dest_1DArray[NUM_DESC];

/*
 *  Callback from MDMA Manager
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void MemDmaCallback(void *pCBParam, uint32_t Event, void *pArg)
{
    /* if (1D Array Descriptor Processed) */
    if (Event == (uint32_t) ADI_DMA_EVENT_DESC_1D_ARRAY_PROCESSED)
    {
        /* Update memory copy status flag */
		bMemCopyInProgress = false;
    }
}

int main(void)
{
    /* DMA Return code */
    ADI_DMA_RESULT      eResult;
    /* Loop variable */
    uint32_t             i;
    /* Memory transfer size in bytes */
    uint32_t            XferSizeInBytes;

    /* Initialize managed drivers and/or services */

    /*
     * Open a Memory DMA Stream
     * Refer to relevant include file with Memory DMA Stream ID definitions for
     * the complete list of Memory DMA stream IDs supported by a processor
     */
    eResult = adi_mdma_Open (MDMA_STREAM_ID,
                             &MemDmaStreamMem[0],
                             &hMemDmaStream,
                             &hSrcDmaChannel,
                             &hDestDmaChannel,
                             NULL, NULL);

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Register callback function if required */
        eResult = adi_dma_UpdateCallback (hMemDmaStream, MemDmaCallback, hMemDmaStream);
    }

    /* Calculate memory transfer size in bytes */
    if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_1BYTE)
    {
        /* 1-byte transfer */
        XferSizeInBytes = 1;
    }
    else if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_2BYTES)
    {
        /* 2-byte transfer */
        XferSizeInBytes = 2;
    }
    else if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_4BYTES)
    {
        /* 4-byte transfer */
        XferSizeInBytes = 4;
    }
    else
    {
        /* Update transfer size for processors that support transfer size more than 4-bytes */
    }

    /* Prepare data buffers for mem copy */

    /*
     * Prepare 1D Array descriptors for memory copy using 1D Array mode
     *
     * FOR (All 1D Array descriptors)
     */
    for (i = 0; i < NUM_DESC; i++)
    {
        /* Source descriptor configuration */

        /* Source buffer start address */
        Src_1DArray[i].pStartAddress    = &SrcDataBuf[i * BYTES_PER_DESC];
        /* DMA Config - only specify memory transfer size */
        Src_1DArray[i].Config           = MDMA_XFER_SIZE;
        Src_1DArray[i].XCount           = (BYTES_PER_DESC/XferSizeInBytes);
        Src_1DArray[i].XModify          = XferSizeInBytes;

        /* Destination descriptor configuration */

        /* Destination buffer start address */
        Dest_1DArray[i].pStartAddress   = &DestDataBuf[i * BYTES_PER_DESC];
        /* DMA Config - only specify memory transfer size */
        Dest_1DArray[i].Config          = MDMA_XFER_SIZE;
        Dest_1DArray[i].XCount          = (BYTES_PER_DESC/XferSizeInBytes);
        Dest_1DArray[i].XModify         = XferSizeInBytes;
    }

    /* Initialize flag */
    bMemCopyInProgress = true;

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Submit 1D Array Descriptors to Source and destination channel */
        eResult = adi_mdma_Copy1DArray (hMemDmaStream, &Dest_1DArray[0], &Src_1DArray[0], NUM_DESC);
    }

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* wait until DMA copy is complete or the time-out counter expires */
        while (bMemCopyInProgress)
        {
            /*
             * Query the current status of Mem copy operation if operating in non-blocking mode
             * This function call is not required for callback mode
             */
            eResult = adi_mdma_IsCopyInProgress (hMemDmaStream, (bool *)&bMemCopyInProgress);
        }
    }

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Close MDMA stream */
        eResult = adi_mdma_Close (hMemDmaStream, false);
    }
    return 0;
}
$END

$BEGIN
/* DMA Manager includes */
\#include <services/dma/adi_dma.h>
\#include <stdlib.h>

/*
 * Memory DMA stream to use
 * Number of Memory DMA streams and stream ID enumerations could vary based on processor family
 * Refer to relevant include file (adi_mdma_streams_xxx.h) for the complete list of
 * Memory DMA stream IDs supported by a processor.
 */
\#if defined (__ADSPBF538_FAMILY__) || defined (__ADSPBF548_FAMILY__) || defined (__ADSPBF561_FAMILY__)
/* Processors with more than one DMA controller, the Memory DMA stream IDs are different from other Blackfin processors */
\#define    MDMA_STREAM_ID      ADI_DMA_MEMDMA0_S0
\#else
/* Processors with one DMA controller */
\#define    MDMA_STREAM_ID      ADI_DMA_MEMDMA_S0
#endif

/* Macro to define the number of 2D Array Descriptors to use */
\#define    NUM_DESC            ($NumDesc)
/* Macro to define the number of bytes to copy per descriptor */
\#define    BYTES_PER_DESC      ($BytesPerDesc)
/* Macro to define the Word/Memory transfer size */
\#define    MDMA_XFER_SIZE      ($eXferSize)
/* Macro to define YCount for 2D transfer */
\#define    MEMCOPY_YCOUNT      ($YCount)

/* MDMA Stream Handle */
static ADI_DMA_STREAM_HANDLE	hMemDmaStream;
/* Source DMA Handle */
ADI_DMA_CHANNEL_HANDLE          hSrcDmaChannel;
/* Destination DMA Handle */
ADI_DMA_CHANNEL_HANDLE          hDestDmaChannel;

/* Memory to handle DMA Stream */
static uint8_t MemDmaStreamMem[ADI_DMA_STREAM_REQ_MEMORY];

/* Flag to register Memory DMA copy completion */
static volatile bool bMemCopyInProgress;

/* Source and destination data buffers */
static uint8_t  SrcDataBuf [BYTES_PER_DESC * NUM_DESC];
static uint8_t  DestDataBuf [BYTES_PER_DESC * NUM_DESC];

/***** Instances to handle 2D Array descriptor transfers ******/
static  ADI_DMA_DESC_ARRAY_2D_MODE  Src_2DArray[NUM_DESC];
static  ADI_DMA_DESC_ARRAY_2D_MODE  Dest_2DArray[NUM_DESC];

/*
 *  Callback from MDMA Manager
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void MemDmaCallback(void *pCBParam, uint32_t Event, void *pArg)
{
    /* if (2D Array Descriptor Processed) */
    if (Event == (uint32_t) ADI_DMA_EVENT_DESC_2D_ARRAY_PROCESSED)
    {
        /* Update memory copy status flag */
		bMemCopyInProgress = false;
    }
}

int main(void)
{
    /* DMA Return code */
    ADI_DMA_RESULT      eResult;
    /* Loop variable */
    uint32_t             i;
    /* Memory transfer size in bytes */
    uint32_t            XferSizeInBytes;

    /* Initialize managed drivers and/or services */

    /*
     * Open a Memory DMA Stream
     * Refer to relevant include file with Memory DMA Stream ID definitions for
     * the complete list of Memory DMA stream IDs supported by a processor
     */
    eResult = adi_mdma_Open (MDMA_STREAM_ID,
                             &MemDmaStreamMem[0],
                             &hMemDmaStream,
                             &hSrcDmaChannel,
                             &hDestDmaChannel,
                             NULL, NULL);

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Register callback function if required */
        eResult = adi_dma_UpdateCallback (hMemDmaStream, MemDmaCallback, hMemDmaStream);
    }

    /* Calculate memory transfer size in bytes */
    if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_1BYTE)
    {
        /* 1-byte transfer */
        XferSizeInBytes = 1;
    }
    else if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_2BYTES)
    {
        /* 2-byte transfer */
        XferSizeInBytes = 2;
    }
    else if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_4BYTES)
    {
        /* 4-byte transfer */
        XferSizeInBytes = 4;
    }
    else
    {
        /* Update transfer size for processors that support transfer size more than 4-bytes */
    }

    /* Prepare data buffers for mem copy */

    /*
     * Prepare 2D Array descriptors for memory copy using 2D Array mode
     *
     * FOR (All 2D Array descriptors)
     */
    for (i = 0; i < NUM_DESC; i++)
    {
        /* Source descriptor configuration */

        /* Source buffer start address */
        Src_2DArray[i].pStartAddress    = &SrcDataBuf[i * BYTES_PER_DESC];
        /* DMA Config - only specify memory transfer size */
        Src_2DArray[i].Config           = MDMA_XFER_SIZE;
        Src_2DArray[i].YCount           = MEMCOPY_YCOUNT;
        Src_2DArray[i].YModify          = XferSizeInBytes;
        Src_2DArray[i].XCount           = (BYTES_PER_DESC/(XferSizeInBytes * MEMCOPY_YCOUNT));
        Src_2DArray[i].XModify          = XferSizeInBytes;

        /* Destination descriptor configuration */

        /* Destination buffer start address */
        Dest_2DArray[i].pStartAddress   = &DestDataBuf[i * BYTES_PER_DESC];
        /* DMA Config - only specify memory transfer size */
        Dest_2DArray[i].Config          = MDMA_XFER_SIZE;
        Dest_2DArray[i].YCount          = MEMCOPY_YCOUNT;
        Dest_2DArray[i].YModify         = XferSizeInBytes;
        Dest_2DArray[i].XCount          = (BYTES_PER_DESC/(XferSizeInBytes * MEMCOPY_YCOUNT));
        Dest_2DArray[i].XModify         = XferSizeInBytes;
    }

    /* Initialize flag */
    bMemCopyInProgress = true;

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Submit 2D Array Descriptors to Source and destination channel */
        eResult = adi_mdma_Copy2DArray (hMemDmaStream, &Dest_2DArray[0], &Src_2DArray[0], NUM_DESC);
    }

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* wait until DMA copy is complete or the time-out counter expires */
        while (bMemCopyInProgress)
        {
            /*
             * Query the current status of Mem copy operation if operating in non-blocking mode
             * This function call is not required for callback mode
             */
            eResult = adi_mdma_IsCopyInProgress (hMemDmaStream, (bool *)&bMemCopyInProgress);
        }
    }

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Close MDMA stream */
        eResult = adi_mdma_Close (hMemDmaStream, false);
    }

    return 0;
}
$END

$BEGIN
/* DMA Manager includes */
\#include <services/dma/adi_dma.h>
\#include <stdlib.h>
\#include <assert.h>

/*
 * Memory DMA stream to use
 * Number of Memory DMA streams and stream ID enumerations could vary based on processor family
 * Refer to relevant include file (adi_mdma_streams_xxx.h) for the complete list of
 * Memory DMA stream IDs supported by a processor.
 */
\#if defined (__ADSPBF538_FAMILY__) || defined (__ADSPBF548_FAMILY__) || defined (__ADSPBF561_FAMILY__)
/* Processors with more than one DMA controller, the Memory DMA stream IDs are different from other Blackfin processors */
\#define    MDMA_STREAM_ID      ADI_DMA_MEMDMA0_S0
\#else
/* Processors with one DMA controller */
\#define    MDMA_STREAM_ID      ADI_DMA_MEMDMA_S0
#endif

/* Macro to define the number of list descriptors to use */
\#define    NUM_DESC            ($NumDesc)
/* Macro to define the number of bytes to copy per descriptor */
\#define    BYTES_PER_DESC      ($BytesPerDesc)
/* Macro to define the Word/Memory transfer size */
\#define    MDMA_XFER_SIZE      ($eXferSize)
/* Macro to define YCount for 2D transfer */
\#define    MEMCOPY_YCOUNT      ($YCount)

/* MDMA Stream Handle */
static ADI_DMA_STREAM_HANDLE	hMemDmaStream;
/* Source DMA Handle */
ADI_DMA_CHANNEL_HANDLE          hSrcDmaChannel;
/* Destination DMA Handle */
ADI_DMA_CHANNEL_HANDLE          hDestDmaChannel;

/* Memory to handle DMA Stream */
static uint8_t MemDmaStreamMem[ADI_DMA_STREAM_REQ_MEMORY];

/* Flag to register Memory DMA copy completion */
static volatile bool bMemCopyInProgress;

/* Source and destination data buffers */
static uint8_t  SrcDataBuf [BYTES_PER_DESC * NUM_DESC];
static uint8_t  DestDataBuf [BYTES_PER_DESC * NUM_DESC];

/***** Instances to handle List descriptor transfers ******/
static  ADI_DMA_DESC_LIST_MODE  Src_List[NUM_DESC];
static  ADI_DMA_DESC_LIST_MODE  Dest_List[NUM_DESC];

/*
 *  Callback from MDMA Manager
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void MemDmaCallback(void *pCBParam, uint32_t Event, void *pArg)
{
    /* IF (Descriptor List Processed) */
    if (Event == (uint32_t) ADI_DMA_EVENT_DESC_LIST_PROCESSED)
    {
        /* Update memory copy status flag */
		bMemCopyInProgress = false;
    }
}

int main(void)
{
    /* DMA Return code */
    ADI_DMA_RESULT      eResult;
    /* Loop variable */
    uint32_t            i;
    /* Memory transfer size in bytes */
    uint32_t            XferSizeInBytes;

    /* Initialize managed drivers and/or services */
	XferSizeInBytes = 1;
	
    /*
     * Open a Memory DMA Stream
     * Refer to relevant include file with Memory DMA Stream ID definitions for
     * the complete list of Memory DMA stream IDs supported by a processor
     */
    eResult = adi_mdma_Open (MDMA_STREAM_ID,
                             &MemDmaStreamMem[0],
                             &hMemDmaStream,
                             &hSrcDmaChannel,
                             &hDestDmaChannel,
                             NULL, NULL);

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Register callback function if required */
        eResult = adi_dma_UpdateCallback (hMemDmaStream, MemDmaCallback, hMemDmaStream);
    }

    /* Calculate memory transfer size in bytes */
    if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_1BYTE)
    {
        /* 1-byte transfer */
        XferSizeInBytes = 1;
    }
    else if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_2BYTES)
    {
        /* 2-byte transfer */
        XferSizeInBytes = 2;
    }
    else if (MDMA_XFER_SIZE == ADI_DMA_MSIZE_4BYTES)
    {
        /* 4-byte transfer */
        XferSizeInBytes = 4;
    }
    else
    {
        /* Update transfer size for processors that support transfer size more than 4-bytes */
		assert(0);
    }

    /* Prepare data buffers for mem copy */

    /*
     * Prepare list descriptors for memory copy
     *
     * FOR (All list descriptors)
     */
    for (i = 0; i < NUM_DESC; i++)
    {
        /* Source descriptor configuration */

        /* Source buffer start address */
        Src_List[i].pStartAddress       = &SrcDataBuf[i * BYTES_PER_DESC];
        /* DMA Config - only specify memory transfer size */
        Src_List[i].Config              = MDMA_XFER_SIZE;
        Src_List[i].YCount              = MEMCOPY_YCOUNT;
        Src_List[i].YModify             = XferSizeInBytes;
        Src_List[i].XModify             = XferSizeInBytes;
        Src_List[i].bCallbackWhenDone   = false;

        /* Destination descriptor configuration */

        /* Destination buffer start address */
        Dest_List[i].pStartAddress      = &DestDataBuf[i * BYTES_PER_DESC];
        /* DMA Config - only specify memory transfer size */
        Dest_List[i].Config             = MDMA_XFER_SIZE;
        Dest_List[i].YCount             = MEMCOPY_YCOUNT;
        Dest_List[i].YModify            = XferSizeInBytes;
        Dest_List[i].XModify            = XferSizeInBytes;
        Dest_List[i].bCallbackWhenDone  = false;

        /* IF (2D transfer) */
        if (MEMCOPY_YCOUNT > 0)
        {
            Src_List[i].XCount          = (BYTES_PER_DESC/(XferSizeInBytes * MEMCOPY_YCOUNT));
            Dest_List[i].XCount         = (BYTES_PER_DESC/(XferSizeInBytes * MEMCOPY_YCOUNT));
        }
        /* ELSE (1D transfer) */
        else
        {
            Src_List[i].XCount          = (BYTES_PER_DESC/XferSizeInBytes);
            Dest_List[i].XCount         = (BYTES_PER_DESC/XferSizeInBytes);
        }

        /* IF (End of list) */
        if (i >= (NUM_DESC-1))
        {
            Src_List[i].pNext = NULL;
            Dest_List[i].pNext = NULL;
        }
        /* ELSE (More descriptors in list) */
        else
        {
            Src_List[i].pNext  = &Src_List[i+1];
            Dest_List[i].pNext = &Dest_List[i+1];
        }
    }

    /* Initialize flag */
    bMemCopyInProgress = true;

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Submit list descriptors to source and destination channel */
        eResult = adi_mdma_CopyQueueList (hMemDmaStream, &Dest_List[0], &Src_List[0]);
    }

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* wait until DMA copy is complete or the time-out counter expires */
        while (bMemCopyInProgress)
        {
            /*
             * Query the current status of Mem copy operation if operating in non-blocking mode
             * This function call is not required for callback mode
             */
            eResult = adi_mdma_IsCopyInProgress (hMemDmaStream, (bool *)&bMemCopyInProgress);
        }
    }

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Close MDMA stream */
        eResult = adi_mdma_Close (hMemDmaStream, false);
    }

    return 0;
}
$END

