    {
        /* 4-byte transfer */
        XferSizeInBytes = 4;
    }
    else
    {
        /* Update transfer size for processors that support transfer size more than 4-bytes */
    }

    /* Prepare data buffers for mem copy */

    /* Initialize flag */
    bMemCopyInProgress = true;

    /* IF (Success) */
    if (eResult == ADI_DMA_SUCCESS)
    {
        /* Submit One-shot 1D buffers to Source and destination channel */
        eResult = adi_mdma_Copy1D (hMemDmaStream,
                                   (void *)&DestDataBuf[0],
                                   (void *)&SrcDataBuf[0],
                                   MDMA_XFER_SIZE,
                                   (BYTES_TO_COPY / XferSizeInBytes));
    }

