$BEGIN
\#include <services/pwm/adi_pwm.h>
\#include <stdio.h>

static ADI_PWM_HANDLE hPwm;
static uint8_t PwmMemory[ADI_PWM_MEMORY_SIZE];

/* PWM Callback */
void Pwm_Callback(void *pCBParam, uint32_t nEvent, void *pArg)
{
    switch(nEvent)
    {
        case ADI_PWM_EVENT_TRIP:
            break;
        case ADI_PWM_EVENT_SYNC:
            break;
        default:
            break;
    }
}

int main(void)
{
    ADI_PWM_RESULT result;

    /* open the PWM driver */
    result = adi_pwm_Open(0, &PwmMemory, ADI_PWM_MEMORY_SIZE, &hPwm);

    /* register a callback */
    result = adi_pwm_RegisterCallback(hPwm, Pwm_Callback, NULL);

    /* set the PWM duty cycle */
    result = adi_pwm_SetDutyCycle(hPwm, $CHANNEL, $DUTYCYCLE);

    /*
     * Use the driver API's to configure PWM
     *
     * adi_pwm_SetPeriod()
     * adi_pwm_EnableSyncOutput()
     * adi_pwm_EnableInterrupt()
     * adi_pwm_EnableChannel()
     */

    result = adi_pwm_Enable(hPwm, true);

    while(1)
    {
        /* wait for PWM callback events */
    }
}
$END

$BEGIN         
/* RTC Manager includes */
\#include <services/rtc/adi_rtc.h>

/* System time include file */
\#include <time.h>

/*  Call back function */
static void RTCCallback(void *pCBParam, uint32_t Event, void *pArg)
{

    switch ( (uint32_t)Event )
    {

        /* one second periodic interrupt */
        case ADI_RTC_EVENT_SECONDS:
           break;

        /* one minute periodic interrupt */
        case ADI_RTC_EVENT_MINUTES :
           break;

        /*  hourly periodic interrupt */
        case ADI_RTC_EVENT_HOURS:
            break;

        /* daily periodic interrupt */
        case ADI_RTC_EVENT_DAYS:
             break;

        /* stop watch count down timeout event */
        case ADI_RTC_EVENT_STOPWATCH:
            break;

        /*  time of day, daily alarm  */
        case ADI_RTC_EVENT_EACH_DAY_ALARM:
            break;

        /*  day & time once only alarm  */
        case ADI_RTC_EVENT_ONCE_ALARM:
             break;

         /*  pending register writes complete */
        case ADI_RTC_EVENT_WRITES_COMPLETE:
            break;

        default:
            break;
    }
    return;
}

int main(void)
{
    /* RTC Return code */
    ADI_RTC_RESULT  eResult;

    /* "tm" structure (see 'time.h') */
    struct tm DateTime;

    /* Initialize managed drivers and/or services */

    /* Initialize the RTC service */
    eResult = adi_rtc_Init();
    if( eResult != ADI_RTC_SUCCESS)
    {
         /* process error return */
    }

    /* set up the fields of the date/time structure with any time */
    DateTime.tm_sec = $Second;             /* $Second seconds */
    DateTime.tm_min = $Minute;             /* $Minute minutes */
    DateTime.tm_hour = $Hour;             /* hour $Hour */
    DateTime.tm_mday = $Day;             /* day of month $Day */
    DateTime.tm_mon = $Month;              /* Month $Month (0-11) */
    DateTime.tm_year = $Year - 1900;   /* year $Year */

    /* Set the given time in the RTC */
    eResult = adi_rtc_SetDateTime( &DateTime );

    /* Set up the fields of the date/time strucutre with the alarm time */
    DateTime.tm_sec = $AlarmSecond;             /* $AlarmSecond seconds */
    DateTime.tm_min = $AlarmMinute;             /* $AlarmMinute minutes */
    DateTime.tm_hour = $AlarmHour;             /* hour $AlarmHour */


    /* Install a call back that will be called day at the specified time */
    eResult = adi_rtc_InstallCallback(ADI_RTC_EVENT_EACH_DAY_ALARM, RTCCallback, (void*)NULL, (void *)&DateTime);

    /* From here on an alarm call back will be generated for every day at $AlarmHour:$AlarmMinute:$AlarmSecond */

    /*
     * Terminate the RTC when not needed
     */
    eResult = adi_rtc_Terminate();

    return (0);
}
$END

$BEGIN         
/* RTC Manager includes */
\#include <services/rtc/adi_rtc.h>

/* System time include file */
\#include <time.h>

/*  Call back function */
static void RTCCallback(void *pCBParam, uint32_t Event, void *pArg)
{

    switch ( (uint32_t)Event )
    {

        /* one second periodic interrupt */
        case ADI_RTC_EVENT_SECONDS:
           break;

        /* one minute periodic interrupt */
        case ADI_RTC_EVENT_MINUTES :
           break;

        /*  hourly periodic interrupt */
        case ADI_RTC_EVENT_HOURS:
            break;

        /* daily periodic interrupt */
        case ADI_RTC_EVENT_DAYS:
             break;

        /* stop watch count down timeout event */
        case ADI_RTC_EVENT_STOPWATCH:
            break;

        /*  time of day, daily alarm  */
        case ADI_RTC_EVENT_EACH_DAY_ALARM:
            break;

        /*  day & time once only alarm  */
        case ADI_RTC_EVENT_ONCE_ALARM:
             break;

         /*  pending register writes complete */
        case ADI_RTC_EVENT_WRITES_COMPLETE:
            break;

        default:
            break;
    }
    return;
}

int main(void)
{
    /* RTC Return code */
    ADI_RTC_RESULT  eResult;

    /* "tm" structure (see 'time.h') */
    struct tm DateTime;

    /* Initialize managed drivers and/or services */

    /* Initialize the RTC service */
    eResult = adi_rtc_Init();
    if( eResult != ADI_RTC_SUCCESS)
    {
         /* process error return */
    }

    /* set up the fields of the date/time structure with any time */
    DateTime.tm_sec = $Second;             /* $Second seconds */
    DateTime.tm_min = $Minute;             /* $Minute minutes */
    DateTime.tm_hour = $Hour;             /* hour $Hour */
    DateTime.tm_mday = $Day;             /* day of month $Day */
    DateTime.tm_mon = $Month;              /* Month $Month (0-11) */
    DateTime.tm_year = $Year - 1900;   /* year $Year */

    /* Set the given time in the RTC */
    eResult = adi_rtc_SetDateTime( &DateTime );
#if ($bSecondEvent == true)

    /* Install a call back that will be called every second */
    eResult = adi_rtc_InstallCallback(ADI_RTC_EVENT_SECONDS, RTCCallback, (void*)NULL, (void *)NULL);
#end
#if ($bMinuteEvent == true)

    /* Install a call back that will be called every minute */
    eResult = adi_rtc_InstallCallback(ADI_RTC_EVENT_MINUTES, RTCCallback, (void*)NULL, (void *)NULL);
#end
#if ($bHourEvent == true)

    /* Install a call back that will be called every hour */
    eResult = adi_rtc_InstallCallback(ADI_RTC_EVENT_HOURS, RTCCallback, (void*)NULL, (void *)NULL);
#end
#if ($bDayEvent == true)

    /* Install a call back that will be called every day */
    eResult = adi_rtc_InstallCallback(ADI_RTC_EVENT_DAYS, RTCCallback, (void*)NULL, (void *)NULL);
#end

    /* From here on a periodic call back will be generated for the periodicity selected */

    /*
     * Terminate the RTC when not needed
     */
    eResult = adi_rtc_Terminate();

    return (0);
}
$END

