$BEGIN

/* Define at least a 4k (minimum) L2 internal memory block to write-protect */

/* declare and place the memory in the "no-init" L2 memory segment */
\#if defined (__ECC__)
#pragma section ("seg_l2_noinit_data", NO_INIT)
#endif

static uint8_t protectedMemory[#size2number($eSize)] __attribute__((aligned(#size2number($eSize))));



/*
 *  Aplication Callback from SMPU
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void smpuCallback(void *pcbParam, uint32_t Event, void *pArg)
{
    /* The SMPU status register is passed back as the "Event",
     * which is a bit-field of which multiple bits may be set.
     *
     * Applications may use adi_smpu_GetInterruptDetails() or
     * adi_smpu_GetBusErrorDetails() to obtain further details
     * pertaining to the violation(s).
     */
    if (BITM_SMPU_STAT_LWERR  & Event) { /* Add code here to process an SMPU lock write error        */ }
    if (BITM_SMPU_STAT_ADRERR & Event) { /* Add code here to process an SMPU address error           */ }
    if (BITM_SMPU_STAT_BEOVR  & Event) { /* Add code here to process an SMPU bus overrun error       */ }
    if (BITM_SMPU_STAT_BERR   & Event) { /* Add code here to process an SMPU bus error               */ }
    if (BITM_SMPU_STAT_IOVR   & Event) { /* Add code here to process an SMPU interrupt overrun error */ }
    if (BITM_SMPU_STAT_IRQ    & Event) { /* Add code here to process an SMPU interrupt request       */ }

    return;
}


int main(void)
{
    ADI_SMPU_HANDLE hSmpu;

    /* open SMPU with a callback address (note: must use the L2 SMPU for L2 memory protection) */
    if (ADI_SMPU_SUCCESS != adi_smpu_Init ($eDevID, NULL, smpuCallback, NULL, &hSmpu)) {
         /* process failed init */
    }

    /*
     * Use the SMPU API's to define and write-protect a test memory region...
     *
     */

    /* reset SMPU */
    if (ADI_SMPU_SUCCESS != adi_smpu_Reset(hSmpu)) {
         /* process failed reset */
    }

    /* enable SMPU interrupts */
    if (ADI_SMPU_SUCCESS != adi_smpu_SetRegionalInterruptEnable(hSmpu, true)) {
         /* process failed interrupt enable */
    }

    /* define an SMPU region on the memory to protect (region size code must match memory size) */
    if (adi_smpu_SetRegionRange(hSmpu, $eRegion, (uint32_t*)&protectedMemory, #size2region($eSize))) {
         /* process failed region range */
    }

    /* enable the region */
    if (adi_smpu_SetRegionEnable(hSmpu, $eRegion, true)) {
         /* process failed region enable */
    }

    /* grant default global r/w access */
    if (adi_smpu_SetSecureGlobalPermissions(hSmpu, ADI_SMPU_SECURITY_RW_ACCESS, ADI_SMPU_SECURITY_RW_ACCESS)) {
         /* process failed global access permissions */
    }

    /* grant default regional r/w access */
    if (adi_smpu_SetSecureRegionPermissions(hSmpu, $eRegion, ADI_SMPU_SECURITY_RW_ACCESS, ADI_SMPU_SECURITY_RW_ACCESS)) {
         /* process failed regional access permissions */
    }

    /* revoke write access to the region */
    
    //This adi_smpu_SetRegionWriteProtectEnable API is not present in the smpu driver for cces 2.6.0
    
    if (adi_smpu_SetRegionWriteProtectEnable(hSmpu, $eRegion, true)) {
         /* process failed regional write protect */
    }

    /* setup blocking from ALL (by default) masters */
    if (adi_smpu_SetRegionBypassMask(hSmpu, $eRegion, ADI_SMPU_BYPASS_REG_A, ADI_SMPU_ID_ALL_MASK)
     || adi_smpu_SetRegionBypassMask(hSmpu, $eRegion, ADI_SMPU_BYPASS_REG_B, ADI_SMPU_ID_ALL_MASK)) {
         /* process failed transaction mask */
    }

    /* Override the region's blocking rule to ALLOW transactions by via specified transaction ID master device.            */
    /* The default value (ADI_SMPU_ID_CRC0_CH1) allows memory writes; in this case, by the MEMDMA0 destination endpoint. */
    if (adi_smpu_SetRegionBypassCode(hSmpu, $eRegion, ADI_SMPU_BYPASS_REG_A, $eTransactionID)) {
        /* process failed transaction mask */
    }


    /*
     *
     * Test memory is now write protected against all access, with the exception the specified transaction ID
     *
     * Access violations are blocked and reported through the application callback.
     *
     * Add other code here to execute while the test memory is write-protected.
     *
     */


    /* when done, release the SMPU, freeing all regions and protections */
    if (adi_smpu_UnInit(hSmpu)) {
         /* process failed SMPU release */
    }

    return 0;
}
$END

