$BEGIN         
\#include <services/spu/adi_spu.h>


int main(void)
{ 
    ADI_SPU_HANDLE hSPU;
    ADI_SPU_RESULT eSPUResult;
    
    eSPUResult = adi_spu_Init (0, NULL /* No memory required for SPU V1 */, &hSPU);
    if( eSPUResult != ADI_SPU_SUCCESS)
    {
         /* process error return */
    }

    /*
     * Use the SPU API's to configure and enable write protection
     *
     */

	/* Disable global lock */
	eSPUResult = adi_spu_EnableGlobalLock(hSPU, false);
    
    /* Unlock the Write Protection configuration */
    eSPUResult = adi_spu_LockWriteProtectionConfig(hSPU, false);
    
    /* Mask writes from core 0 */
    eSPUResult = adi_spu_SetCoreWriteProtectMask(hSPU, $PeripheralID, ADI_SPU_CORE_MASTER_0);
    
    /* Mask the writes from system master 1  */
    eSPUResult = adi_spu_SetSysWriteProtectMask(hSPU, $PeripheralID, ADI_SPU_SYSTEM_MASTER_0);
    
    /* Add more calls here to write protect different peripherals from core and system masters */

    /* Lock the write protect configuration */    
    eSPUResult = adi_spu_LockWriteProtectionConfig(hSPU, true); 
    
    /* Enable back the global lock */
    eSPUResult = adi_spu_EnableGlobalLock(hSPU, true);
    
    return 0;
}
$END

$BEGIN         
\#include <services/spu/adi_spu.h>
\#include <stdlib.h>

/*
 *  Callback from SPU
 *
 * Parameters
 *  - [in]  pCBParam    Callback parameter supplied by application
 *  - [in]  Event       Callback event
 *  - [in]  pArg        Callback argument
 *
 * Returns  None
 *
 */
static void SpuCallback(void *pCBParam, uint32_t Event, void *pArg)
{
    switch(Event)
    {
        /*! Indicates that there was an attempted write to a register
         *  in the SPU when write protection lock and global lock
         *  were enabled. */
        case ADI_SPU_EVENT_LOCK_WRITE_ERROR:
        
            /* Add code here to handle lock write error */
            break;
       
        /*! Indicates that a security and/or protection violation has
         *  been detected and an interrupt is asserted. */
        case ADI_SPU_EVENT_VIOLATION_INT:
        
            /* Add code here to handle violation interrupt */
            break;

        default:
            break;

    }

    return;
}

/* Memory required for SPU operation */
static uint8_t SpuMemory[ADI_SPU_MEMORY_SIZE];

int main(void)
{ 
    ADI_SPU_HANDLE hSPU;
    ADI_SPU_RESULT eSPUResult;
    
    eSPUResult = adi_spu_Init (0, SpuMemory, SpuCallback, NULL, &hSPU);
    if( eSPUResult != ADI_SPU_SUCCESS)
    {
         /* process error return */
    }

    /*
     * Use the SPU API's to configure and enable write protection
     *
     */

	/* Disable global lock */
	eSPUResult = adi_spu_EnableGlobalLock(hSPU, false);
    
    /* Unlock the Secure Protection configuration */
    eSPUResult = adi_spu_LockSecureConfig(hSPU, false);
    
    /* Enable test peripheral slave security */
    eSPUResult = adi_spu_EnableSlaveSecure(hSPU, $PeripheralID, true);
    
    /* Configure peripheral to generate secure transactions */
    eSPUResult = adi_spu_EnableMasterSecure(hSPU, $PeripheralID, true);
    
    /* Add more calls here to configure security for other peripherals */

    /* Lock the security configuration */
    eSPUResult = adi_spu_LockSecureConfig(hSPU, true);
    
    /* Enable back the global lock */
    eSPUResult = adi_spu_EnableGlobalLock(hSPU, true);
    
    return 0;
}
$END

