$BEGIN 
\#include <services/stdio/adi_stdio.h>

int init_uart_stdio(ADI_STDIO_DEVICE_HANDLE *phSTDIOJTAG, ADI_STDIO_DEVICE_HANDLE *phSTDIOUART)
{
    /* Initialize the STDIO service */
    if(adi_stdio_Init(phSTDIOJTAG) != ADI_STDIO_RESULT_SUCCESS)
    {
    	return 0;
    }

    /* Register UART device type with STDIO service */
    adi_stdio_RegisterUART();

    /* Open UART Device for STDIO*/
    if(adi_stdio_OpenDevice (ADI_STDIO_DEVICE_TYPE_UART, $uartDeviceNumber, phSTDIOUART)
        != ADI_STDIO_RESULT_SUCCESS)
    {
    	return 0;
    }

    /* Set character echo for UART device */
    if(adi_stdio_ControlDevice(*phSTDIOUART, ADI_STDIO_COMMAND_ENABLE_CHAR_ECHO, (void *) true)
		!= ADI_STDIO_RESULT_SUCCESS)
    {
    	return 0;
    }

    /* Redirect stream to UART */
    if(adi_stdio_RedirectStream(*phSTDIOUART, $streamType)
		!= ADI_STDIO_RESULT_SUCCESS)
    {
    	return 0;
    }

    /* Set baud rate for UART device */
    if(adi_stdio_ControlDevice(*phSTDIOUART, ADI_STDIO_COMMAND_SET_UART_BAUD_RATE, (void *)$baudRate)
		!= ADI_STDIO_RESULT_SUCCESS)
    {
    	return 0;
    }

    return 1;
}

$END

$BEGIN         
\#if !defined(__ADSPARM__) 
\#include <services/tmr/adi_ctmr.h>



/* Core Timer callback functuion */
static void CTimerHandler(void *pCBParam, uint32_t Event, void *pArg)
{
    switch( Event )
    {
      /* In the case of the core time ADI_CTIMER_EXPIRED is the only valid event */
      case ADI_CTIMER_EXPIRED:
          break;
      default:
          break;
    }
    return;
}
#endif

int main(void)
{

\#if !defined(__ADSPARM__) 
    ADI_CTMR_HANDLE phCTimer;
    ADI_CTMR_RESULT eCTmrResult;
 
\#if defined (__ADSPBLACKFIN__)
    eCTmrResult = adi_ctmr_Open (ADI_CTMR_DEV0, CTimerHandler, 0 /* no callback parameter*/, &phCTimer);
    if( eCTmrResult != ADI_CTMR_SUCCESS)
    {
         /* process error return */
    }
\#else
    eCTmrResult = adi_ctmr_Open (ADI_CTMR_DEV0, ADI_CTMR_PRIORITY_HIGH, CTimerHandler, 0 /* no callback parameter*/, &phCTimer);
    if( eCTmrResult != ADI_CTMR_SUCCESS)
    {
         /* process error return */
    }
#endif

    /*
     * Use the core timer's API's to configure and enable the core timer
     *
     */

    eCTmrResult = adi_ctmr_SetPeriod(phCTimer, $period);
\#if defined (__ADSPBLACKFIN__)
    eCTmrResult = adi_ctmr_SetScale(phCTimer, $scale);
#endif
    eCTmrResult = adi_ctmr_Enable(phCTimer, true);

\#if defined (__ADSPBLACKFIN__)
    eCTmrResult = adi_ctmr_EnableAutoReload(phCTimer, true);
    eCTmrResult = adi_ctmr_Activate(phCTimer, true);
#endif       
    /*
     * From here a core timer callback will generated at a frequency that is a function 
     * of the period and the scale.
     */
#endif     
}
$END

$BEGIN         
\#include <services/tmr/adi_tmr.h>
\#include <stddef.h>

/* Timer event handler */
static void TimerHandler(void *pCBParam, uint32_t Event, void *pArg)
{
    switch(Event)
    {
        case ADI_TMR_EVENT_DATA_INT:
        	/* Handle the timer event here */
            break;

        default:
            break;
    }

    return;
}

uint8_t TimerMemory[ADI_TMR_MEMORY];

uint32_t main(void)
{ 
    /* Timer handle */
    ADI_TMR_HANDLE   hTimer;
    
    ADI_TMR_RESULT 	 eTmrResult;
    
    /* Open the timer */
    if( (eTmrResult = adi_tmr_Open ($nTimer,
                		TimerMemory,
                		ADI_TMR_MEMORY,
                		TimerHandler,
                		NULL,
                		&hTimer)) != ADI_TMR_SUCCESS)
     {
         /* Failed to open the timer handle the error here */
     }
    
    /*
     * Use the GP timer's API's to configure and enable the timer
     *
     */

	/* Set the mode to PWM OUT */
    eTmrResult = adi_tmr_SetMode(hTimer, ADI_TMR_MODE_CONTINUOUS_PWMOUT);
    
    /* Set the IRQ mode to get interrupt after timer counts to Delay + Width */
    eTmrResult = adi_tmr_SetIRQMode(hTimer, ADI_TMR_IRQMODE_WIDTH_DELAY);

	/* Set the Period */
    eTmrResult = adi_tmr_SetPeriod(hTimer, $period);
    
    /* Set the timer width */
	eTmrResult = adi_tmr_SetWidth(hTimer, $width);
	
	/* Set the timer delay */
	eTmrResult = adi_tmr_SetDelay(hTimer, $delay);
	
	/* Enable the timer */
	eTmrResult = adi_tmr_Enable(hTimer, true);
	        
    /*
     * From here a GP timer PWM output will generated continuously and a callback is generated 
     * every time the width+delay value expires. Once the timer expires the delay, width, period
     * registers are loaded back automatically.
     */
     
     /* 
      * Close the timer when not needed 
      */
      
     /* Disable the timer */
     eTmrResult = adi_tmr_Enable(hTimer, false);
      
     /* Close the timer */
     eTmrResult = adi_tmr_Close(hTimer);
      
     return 0;
}
$END

