$BEGIN
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

/* TRU Manager includes */
\#include <services/tru/adi_tru.h>

/* rename the TRU software trigger master macro on 70x targets */
\#if defined( __ADSPBF707_FAMILY__)
\#define TRGM_SOFT0 TRGM_SOFT0_MST
#endif

int main(void)
{
    /* TRU Return code */
    ADI_TRU_RESULT	eResult;

    /* Initialize managed drivers and/or services */

    /* Initialize the TRU service and reset the hardware */
    eResult = adi_tru_Init (true);

	/*
	 * This example uses Software-driven Trigger 0 to generate an outgoing trigger (Master) and
	 * Memory DMA Stream 0 Destination channel as trigger slave waiting for a trigger input.
	 * Other TRU uses may employ different peripherals and trigger routings; DMA is not a requirement for TRU.
	 *
	 */

\#if defined(__ADSPSC589_FAMILY__)
    /* On ADSP-SC58x: L2 is secure-access-only by default, so use SPU service to modify access for MDMA stream */
    /* Use adi_spu_Init(...) to open the SPU service... */
    /* Use adi_spu_EnableMasterSecure(..., SPU_MDMA_STREAM_ID, ...) to grant non-secure L2 access to the MDMA stream... */

    /* Also, the ADSP-58x routes the MDMA0 & MDMA1 streams through the CRC unit, */
    /* which requires CRC configuration or a switch to either of the enhMDMA streams 2 & 3. */
    /* (This code sketch uses MDMA0 exclusively) */
#endif

    /* open adi_mdma_Open(...) to open an MDMA stream */

	/* Route a Trigger Slave to a Software-driven trigger Master */
	eResult = adi_tru_ConfigureSlave (TRGS_MDMA0_DST, TRGM_SOFT0);

	/*
	 * Configure Trigger Input settings of the trigger slave routed to
	 * the software-driven trigger master using driver specific trigger input
	 * configuration APIs
	 */

	 /*
	  * Submit buffer(s) to the slave device
	  */

	/*
	 * Generate an outgoing software-driven trigger
	 * This example uses Software-driven Trigger 0
	 */
	eResult = adi_tru_RaiseTriggerMaster (TRGM_SOFT0);

	/*
	 * Clear the trigger routing that was established earlier so that
	 * the slave device doesn't receive an unexpected trigger input
	 *
	 * This example uses Memory DMA Stream 0 Destination channel as trigger slave
	 *
	 */
	 eResult = adi_tru_ConfigureSlave(TRGS_MDMA0_DST, 0);

\#if defined(__ADSPSC589_FAMILY__)
	/* Use adi_spu_UnInit(...) to close the SPU */
#endif

	/* Use adi_mdma_Close() to close the stream */

    /* Shutdown the TRU service */
    eResult = adi_tru_UnInit ();
    return 0;
}
$END

$BEGIN
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

/* TRU Manager includes */
\#include <services/tru/adi_tru.h>
/* DMA Manager includes */
\#include <services/dma/adi_dma.h>
/* NULL definitions */
\#include <string.h>

/* rename the TRU software trigger master macro on 70x targets */
\#if defined( __ADSPBF707_FAMILY__)
\#define TRGM_SOFT0 (TRGM_SOFT0_MST)
#endif

/* DMA Stream Handle */
static ADI_DMA_STREAM_HANDLE    hMemDmaStream;

/* Source DMA Handle */
static ADI_DMA_CHANNEL_HANDLE   hSrcDmaChannel;

/* Destination DMA Handle */
static ADI_DMA_CHANNEL_HANDLE   hDestDmaChannel;

/* Memory to handle DMA Stream */
static uint8_t  MemDmaStreamMem[ADI_DMA_STREAM_REQ_MEMORY];

int main(void)
{
	/* DMA Return code */
    ADI_DMA_RESULT 	eDmaResult;
    /* TRU Return code */
    ADI_TRU_RESULT	eTruResult;

    /* Initialize managed drivers and/or services */

    /* Open a TRU device instance */
    eTruResult = adi_tru_Init (true);

\#if defined(__ADSPSC589_FAMILY__)
    /* On ADSP-SC58x: L2 is secure-access-only by default, so use SPU service to modify access for MDMA stream */
    /* Use adi_spu_Init(...) to open the SPU service... */
    /* Use adi_spu_EnableMasterSecure(..., SPU_MDMA_STREAM_ID, ...) to grant non-secure L2 access to the MDMA stream... */

    /* Also, the ADSP-58x routes the MDMA0 & MDMA1 streams through the CRC unit, */
    /* which requires CRC configuration or a switch to either of the enhMDMA streams 2 & 3. */
    /* (This code sketch uses MDMA0 exclusively) */
#endif

	/*
	 * Open a Memory DMA Stream
	 * This example uses Memory DMA Stream 0
	 */
	 eDmaResult = adi_mdma_Open (ADI_DMA_MEMDMA_S0, &MemDmaStreamMem[0], &hMemDmaStream,
                                 &hSrcDmaChannel, &hDestDmaChannel, NULL, NULL);

	/*
	 * Route a Trigger Slave to a Software-driven trigger Master
	 *
	 * This example uses Software-driven Trigger 0 to generate an outgoing trigger (Master) and
	 * Memory DMA Stream 0 Destination channel as trigger slave waiting for a trigger input.
	 *
	 */
	eTruResult = adi_tru_ConfigureSlave (TRGS_MDMA0_DST, TRGM_SOFT0);

	/*
	 * Configure Trigger Input settings of the trigger slave routed to
	 * the software-driven trigger master
	 * This example uses Memory DMA Stream 0 Destination channel as trigger slave
	 * waiting for a trigger input
	 */
	 eDmaResult = adi_dma_ConfigTriggerIn (hDestDmaChannel, true, false);

	 /*
	  * Submit One-shot 1D buffers to Source and destination channel of Memory DMA stream
	  * The Memory DMA transfer will not start until it receives a trigger input
	  * for its corresponding trigger master
	  */

	/*
	 * Generate an outgoing software-driven trigger
	 * This example uses Software-driven Trigger 0
	 */
	eTruResult = adi_tru_RaiseTriggerMaster (TRGM_SOFT0);

	/*
	 * Clear the trigger routing that was established earlier so that
	 * the slave device doesn't receive an unexpected trigger input
	 *
	 * This example uses Memory DMA Stream 0 Destination channel as trigger slave
	 *
	 */
	 eTruResult = adi_tru_ConfigureSlave (TRGS_MDMA0_DST, 0);

\#if defined(__ADSPSC589_FAMILY__)
	/* Use adi_spu_UnInit(...) to close the SPU */
#endif

	/* Close MDMA stream */
	eDmaResult = adi_mdma_Close (hMemDmaStream, false);

    /* Shutdown the TRU service */
    eTruResult = adi_tru_UnInit ();
    return 0;
}
$END

$BEGIN
\#if defined (__ADSPARM__)
/* Some variables in this code sketch are set for demonstration purposes
 * but not used. These variables are expected to be used in real
 * applications.
 */

#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#endif

/* TRU Manager includes */
\#include <services/tru/adi_tru.h>
/* DMA Manager includes */
\#include <services/dma/adi_dma.h>
\#include <drivers/uart/adi_uart.h>
/* NULL definitions */
\#include <string.h>

/* rename the TRU software trigger master macro on 70x targets */
\#if defined( __ADSPBF707_FAMILY__)
\#define TRGM_SOFT0 (TRGM_SOFT0_MST)
#endif

/* UART Device Handle */
static ADI_UART_HANDLE hUartDev;

/* DMA Stream Handle */
static ADI_DMA_STREAM_HANDLE    hMemDmaStream;

/* Source DMA Handle */
static ADI_DMA_CHANNEL_HANDLE   hSrcDmaChannel;

/* Destination DMA Handle */
static ADI_DMA_CHANNEL_HANDLE   hDestDmaChannel;

/* Memory to handle DMA Stream */
static uint8_t  MemDmaStreamMem[ADI_DMA_STREAM_REQ_MEMORY];

/* UART Device memory */
static uint8_t  UartDevMemory[ADI_UART_UNIDIR_DMA_MEMORY_SIZE];

int main(void)
{
	/* DMA Return code */
    ADI_DMA_RESULT 	eDmaResult;
    /* TRU Return code */
    ADI_TRU_RESULT	eTruResult;
    /* UART Return code */
    ADI_UART_RESULT eUartResult;

    /* Initialize managed drivers and/or services */

    /* Open a TRU device instance */
    eTruResult = adi_tru_Init (true);

\#if defined(__ADSPSC589_FAMILY__)
    /* On ADSP-SC58x: L2 is secure-access-only by default, so use SPU service to modify access for MDMA stream */
    /* Use adi_spu_Init(...) to open the SPU service... */
    /* Use adi_spu_EnableMasterSecure(..., SPU_MDMA_STREAM_ID, ...) to grant non-secure L2 access to the MDMA stream... */

    /* Also, the ADSP-58x routes the MDMA0 & MDMA1 streams through the CRC unit, */
    /* which requires CRC configuration or a switch to either of the enhMDMA streams 2 & 3. */
    /* (This code sketch uses MDMA0 exclusively) */
#endif

	/*
	 * Open a Memory DMA Stream
	 * This example uses Memory DMA Stream 0
	 */
	 eDmaResult = adi_mdma_Open (ADI_DMA_MEMDMA_S0, &MemDmaStreamMem[0], &hMemDmaStream,
                                 &hSrcDmaChannel, &hDestDmaChannel, NULL, NULL);

	/*
     * Open Slave device to receive trigger input
     * This example uses UART device 0 as slave device
     */
    eUartResult = adi_uart_Open (0, ADI_UART_DIR_TRANSMIT, &UartDevMemory[0], ADI_UART_UNIDIR_DMA_MEMORY_SIZE, &hUartDev);

    /*
	 * Route a Trigger Slave to a Trigger Master
	 *
	 * This example uses Memory DMA Stream 0 Destination channel to generate an outgoing trigger (Master) and
	 * UART 0 TX DMA channel as trigger slave waiting for a trigger input.
	 *
	 */
	eTruResult = adi_tru_ConfigureSlave (TRGS_UART0_TXDMA, TRGM_MDMA0_DST);

    /*
     * Configure Trigger input settings of the Slave device using driver specific APIs
     * This example shows how to configure UART 0 TX DMA channel trigger input settings
     */
    eUartResult = adi_uart_ConfigTxTriggerIn (hUartDev, true, false);

    /*
     * Submit buffers to trigger slave device expecting a trigger input
     */

    /*
     * Configure Trigger Output settings
     * Memory DMA Stream 0 Destination channel configured to generate a trigger when X-Count expires
     */
     eDmaResult = adi_dma_ConfigTriggerOut (hDestDmaChannel, ADI_DMA_TRIGGER_OUT_XCNT_EXPIRY);

	/*
	 * Submit One-shot 1D buffers to source and destination channel of Memory DMA stream
	 * In this example, the destination channel generates an outgoing trigger
     * after processing the data buffer
	 */

    /*
     * The trigger slave device starts processing its data buffer soon after it receives the trigger
     */

	/*
	 * Clear the trigger routing that was established earlier so that
	 * the slave device doesn't receive an unexpected trigger input
	 *
	 * This example uses UART 0 TX DMA channel as trigger slave
	 *
	 */
	 eTruResult = adi_tru_ConfigureSlave (TRGS_UART0_TXDMA, 0);

    /* Close UART */
    eUartResult = adi_uart_Close (hUartDev);

\#if defined(__ADSPSC589_FAMILY__)
	/* Use adi_spu_UnInit(...) to close the SPU */
#endif

	/* Close MDMA stream */
	eDmaResult = adi_mdma_Close (hMemDmaStream, false);

    /* Shutdown the TRU service */
    eTruResult = adi_tru_UnInit ();
    return 0;
}
$END
